// ── ชิ้นส่วนเล็ก ────────────────────────────────────────────────────
function Seg({ label, value, options, onPick }: {
  label: string; value: string; options: Array<[string, string]>; onPick: (v: string) => void;
}) {
  return (
    <div className="flex flex-col gap-1.5">
      <span className="text-[13px] font-semibold">{label}</span>
      <div className="flex gap-2 flex-wrap">
        {options.map(([v, l]) => {
          const on = value === v;
          return (
            <button key={v} className="h-9 px-3.5 rounded-lg text-[13px]"
              style={{
                background: on ? 'linear-gradient(135deg,#f7d778,#e0a82e 55%,#c98a16)' : '#fff',
                border: on ? 'none' : '1px solid var(--color-ink-line)',
                fontWeight: on ? 600 : 400,
                color: on ? '#3a2a08' : 'var(--color-cream)',
              }}
              onClick={() => onPick(v)}>{l}</button>
          );
        })}
      </div>
    </div>
  );
}

function Slider({ label, unit, v, min, max, step, onChange }: {
  label: string; unit: string; v: number; min: number; max: number; step: number; onChange: (n: number) => void;
}) {
  return (
    <div className="flex flex-col gap-1">
      <div className="flex items-baseline gap-2">
        <span className="text-[13px] font-semibold flex-1">{label}</span>
        <span className="text-[13px] tnum">{num(v)} {unit}</span>
      </div>
      <input type="range" min={min} max={max} step={step} value={v}
        onChange={(e) => onChange(Number(e.target.value))}
        className="w-full accent-[var(--color-gold)]" />
    </div>
  );
}
