// ════════════════════════════════════════════════════════════════════
//  แถบควบคุมเสียง — ติดขอบล่างเสมอตอนอยู่ในจอเขียนโน้ต
//
//  ★ เล่น / หยุด แยกเป็นสองปุ่ม (ไม่ใช่ปุ่มเดียวสลับ) — ผู้ใช้ที่ไม่ถนัดคอม
//    ต้องเห็นว่า "หยุด" อยู่ตรงไหนตลอดเวลา ไม่ต้องเดาว่าปุ่มตอนนี้เป็นอะไร
//  ★ ตำแหน่งเขียนเป็น "ท่อน 1 · ห้อง 12" — เลขสากลตามกฎทั้งโปรเจกต์ (ดู lib/num.ts)
//  ★ "ฉิ่ง–ฉับ" ไม่แปลแม้เปลี่ยนเป็นภาษาอังกฤษ — เป็นชื่อเครื่องประกอบจังหวะไทย
// ════════════════════════════════════════════════════════════════════
import { useState } from 'react';
import { TUNING_SYSTEMS } from '../../packages/engine/thai_tuning.mjs';
import { num } from '../lib/num';
import { t, tuningLabel } from '../lib/i18n';
import type { AudioLevels } from '../screens/Editor';

type Props = {
  playing: boolean;
  onPlay: () => void;
  onStop: () => void;
  onPlayFrom: () => void;
  selBarLabel: string | null;
  bpm: number;
  onBpm: (n: number) => void;
  /** ★ ปุ่มนี้คุม **ตัวหนังสือฉิ่ง–ฉับ บนกระดาษ** ไม่ใช่เสียง (เจ้าของสั่ง 2026-08-16
   *  หลังมีปุ่มปิดเสียงฉิ่งในแผงความดัง — ของเดิมสองปุ่มทำหน้าที่ซ้ำกัน) */
  chingShow: boolean;
  onChingShow: (v: boolean) => void;
  /** ซ้ำท่อนตามจำนวนเที่ยวที่เขียนไว้ที่หัวท่อน */
  repeatOn: boolean;
  onRepeat: (v: boolean) => void;
  tuning: string;
  onTuning: (id: string) => void;
  /** โวลุ่ม/ปิดเสียง แยกเครื่องดนตรีกับฉิ่ง–ฉับ (ลูกค้าขอ 2026-08-16) */
  audio: AudioLevels;
  onAudio: (next: AudioLevels) => void;
  /** ตำแหน่งในเพลง 0-1 · null = ยังไม่เริ่ม */
  progress: number | null;
  sectionMarks: Array<{ at: number; name: string }>;
  onSeek: (ratio: number) => void;
  posLabel: string;
  loading?: boolean;
};

/** แถวปรับเสียงหนึ่งเส้น — ปุ่มปิดเสียง + สไลเดอร์ + ตัวเลข
 *  ★ ปุ่มปิดเสียงต้องเป็นปุ่มของตัวเอง **ไม่ใช่ลากสไลเดอร์ไปสุดซ้าย** — ปิดแล้ว
 *    เปิดกลับต้องได้ความดังเดิม ไม่ต้องจำว่าเมื่อกี้อยู่กี่เปอร์เซ็นต์ */
function VolRow({ label, hint, value, muted, onValue, onMute }: {
  label: string; hint: string; value: number; muted: boolean;
  onValue: (v: number) => void; onMute: (v: boolean) => void;
}) {
  return (
    <div className="flex items-center gap-2.5">
      <button
        className="w-[34px] h-[30px] flex-none grid place-items-center rounded-[9px] border text-[13px]"
        style={{
          background: muted ? 'rgba(226,59,46,.1)' : '#fff',
          borderColor: muted ? 'rgba(226,59,46,.45)' : 'var(--color-ink-line)',
          color: muted ? 'var(--color-siam)' : 'var(--color-cream-muted)',
        }}
        title={muted ? t('เปิดเสียงกลับ') : t('ปิดเสียงเส้นนี้')}
        onClick={() => onMute(!muted)}
      >
        {muted ? '🔇' : '🔊'}
      </button>
      <div className="flex flex-col gap-0.5 min-w-[188px]">
        <div className="flex items-center gap-2">
          <span className="text-[12.5px] flex-1" style={{ opacity: muted ? 0.5 : 1 }}>{label}</span>
          <span className="text-[11.5px] tnum text-[var(--color-cream-muted)]">
            {muted ? t('ปิดอยู่') : `${num(Math.round(value * 100))}%`}
          </span>
        </div>
        <input
          type="range" min={0} max={100} step={5}
          value={Math.round(value * 100)}
          disabled={muted}
          onChange={(e) => onValue(Number(e.currentTarget.value) / 100)}
          style={{ accentColor: '#c98a16', opacity: muted ? 0.4 : 1 }}
        />
        <span className="text-[11px] text-[var(--color-cream-dim)]">{hint}</span>
      </div>
    </div>
  );
}

export default function TransportBar(p: Props) {
  const [volOpen, setVolOpen] = useState(false);
  const anyMuted = p.audio.muteInst || p.audio.muteChing;
  return (
    <div className="no-print h-[56px] flex-none flex items-center gap-3.5 px-4 glass-bar border-t border-[var(--color-ink-line)] relative z-20">
      <div className="flex gap-1.5">
        <button
          className="w-11 h-[38px] grid place-items-center rounded-[11px] btn-gold text-[15px]"
          onClick={p.onPlay}
          title={t('เล่น / หยุด — เคาะ Spacebarก็ได้ · หยุดแล้วกดอีกทีจะเล่นต่อจากห้องที่หยุดไว้')}
          disabled={p.loading}
        >
          ▶
        </button>
        <button
          className="w-10 h-[38px] grid place-items-center rounded-[11px] btn-glass text-[12px]"
          onClick={p.onStop}
          title={t('หยุด (Ctrl+.)')}
          disabled={!p.playing}
        >
          ■
        </button>
        <button
          className="h-[38px] px-3 flex items-center gap-1.5 rounded-[11px] btn-glass text-[12.5px] whitespace-nowrap"
          onClick={p.onPlayFrom}
          title={t('เล่นจากห้องที่เลือก (Ctrl+Enter)')}
          disabled={!p.selBarLabel || p.loading}
        >
          ▶ {t('เล่นจากห้อง')} {p.selBarLabel ?? '—'}
        </button>
      </div>

      <div className="w-px h-[26px] bg-[var(--color-ink-line)]" />

      {/* ── โวลุ่มแยกเครื่องดนตรี / ฉิ่ง–ฉับ (ลูกค้าขอ 2026-08-16) ─────────
          ★ ปุ่มบนแถบต้องบอกสถานะได้ทันทีว่า **มีอะไรถูกปิดเสียงอยู่หรือเปล่า** —
            ไม่งั้นผู้ใช้ปิดเสียงค้างไว้แล้วเปิดเพลงใหม่ จะนึกว่าโปรแกรมเสีย
          ★ แผงอยู่ในป๊อปอัป ไม่ใช่กางบนแถบ เพราะแถบล่างเต็มแล้ว (เล่น · ความเร็ว ·
            ฉิ่ง · ซ้ำท่อน · เทียบเสียง · แถบตำแหน่ง) ยัดสไลเดอร์สองตัวลงไปอีก
            ทุกอย่างจะเบียดจนกดพลาด */}
      <div className="relative">
        {/* ★ ป้ายคงที่ + กว้างคงที่ — สถานะบอกด้วยไอคอน/สี ไม่ใช่ด้วยการเปลี่ยนคำ
            (เจ้าของสั่ง 2026-08-16: ปุ่มบนแถบล่างห้ามยืด-หดตามข้อความ) */}
        <button
          className="w-[120px] flex-none flex items-center gap-2 h-[34px] px-3 rounded-[10px] text-[12.5px] whitespace-nowrap border"
          style={{
            background: anyMuted ? 'rgba(226,59,46,.08)' : volOpen ? 'rgba(224,168,46,.16)' : '#fff',
            borderColor: anyMuted ? 'rgba(226,59,46,.4)' : volOpen ? 'rgba(224,168,46,.45)' : 'var(--color-ink-line)',
            color: anyMuted ? 'var(--color-siam)' : volOpen ? 'var(--color-gold-deep)' : 'var(--color-cream-muted)',
            fontWeight: anyMuted || volOpen ? 600 : 400,
          }}
          onClick={() => setVolOpen((v) => !v)}
          title={anyMuted
            ? t('มีเสียงที่ถูกปิดอยู่ — กดเพื่อเปิดแผงความดัง')
            : t('ปรับความดัง — เครื่องดนตรีกับฉิ่ง–ฉับ แยกกัน')}
        >
          {anyMuted ? '🔇' : '🔊'}
          {t('ความดัง')}
        </button>
        {volOpen && (
          <>
            {/* คลิกที่อื่นเพื่อปิด — ต้องมี ไม่งั้นแผงค้างทับปุ่มอื่นจนกดไม่ได้ */}
            <div className="fixed inset-0 z-[60]" onMouseDown={() => setVolOpen(false)} />
            <div
              className="absolute z-[61] left-0 bottom-[calc(100%+8px)] rounded-2xl p-4 flex flex-col gap-3.5"
              style={{
                width: 268,
                background: 'rgba(255,255,255,.98)',
                border: '1px solid rgba(255,255,255,.85)',
                boxShadow: '0 24px 56px -20px rgba(0,0,0,.42)',
              }}
            >
              <VolRow
                label={t('เครื่องดนตรี')}
                hint={t('ตัวโน้ตทุกตัวในเพลง')}
                value={p.audio.inst}
                muted={p.audio.muteInst}
                onValue={(v) => p.onAudio({ ...p.audio, inst: v })}
                onMute={(v) => p.onAudio({ ...p.audio, muteInst: v })}
              />
              {/* ★ ฉิ่ง–ฉับ ไม่แปล — เป็นชื่อเครื่องประกอบจังหวะไทย */}
              <VolRow
                label="ฉิ่ง–ฉับ"
                hint={t('ปิดเสียงไว้ยังนับจังหวะบนกระดาษเหมือนเดิม')}
                value={p.audio.ching}
                muted={p.audio.muteChing}
                onValue={(v) => p.onAudio({ ...p.audio, ching: v })}
                onMute={(v) => p.onAudio({ ...p.audio, muteChing: v })}
              />
              <p className="text-[11.5px] text-[var(--color-cream-muted)] leading-relaxed border-t border-[var(--color-ink-line)] pt-2.5">
                {t('ปรับได้ระหว่างเล่นอยู่ · ค่านี้เป็นของโปรแกรม ไม่ติดไปกับไฟล์เพลง')}
              </p>
            </div>
          </>
        )}
      </div>

      <div className="flex items-center gap-1.5">
        <span className="text-[12px] text-[var(--color-cream-muted)]">{t('ความเร็ว')}</span>
        <div className="flex items-center h-[34px] rounded-[10px] bg-white border border-[var(--color-ink-line)] overflow-hidden">
          <button
            className="w-[30px] h-full grid place-items-center text-[15px] text-[var(--color-cream-muted)] hover:bg-[rgba(224,168,46,.14)]"
            onClick={() => p.onBpm(Math.max(20, p.bpm - 2))}
            title={t('ช้าลง (Ctrl+[)')}
          >
            −
          </button>
          <div className="min-w-[64px] text-center text-[13.5px] font-semibold tnum">
            {num(p.bpm)} <span className="text-[10.5px] font-normal text-[var(--color-cream-dim)]">BPM</span>
          </div>
          <button
            className="w-[30px] h-full grid place-items-center text-[15px] text-[var(--color-cream-muted)] hover:bg-[rgba(224,168,46,.14)]"
            onClick={() => p.onBpm(Math.min(240, p.bpm + 2))}
            title={t('เร็วขึ้น (Ctrl+])')}
          >
            ＋
          </button>
        </div>
      </div>

      {/* ── แสดง/ซ่อน ตัวหนังสือ "ฉิ่ง–ฉับ" บนกระดาษ ────────────────────
          ★★ ปุ่มนี้ **ไม่เกี่ยวกับเสียง** ★★ เจ้าของสั่ง 2026-08-16: ของเดิมเป็น
          "ฉิ่งดัง/ไม่ดัง" ซึ่งซ้ำกับปุ่มปิดเสียงฉิ่งในแผงความดังที่เพิ่งเพิ่ม
          → ย้ายมาคุมหน้าตากระดาษแทน (บางคนว่าตัวหนังสือฉิ่ง–ฉับ ทำให้กระดาษรก)
          ★ มีผลทั้งบนจอและบนกระดาษที่พิมพ์ออกมา — เลขห้องกับเส้นตารางยังอยู่ครบ */}
      <button
        className="w-[168px] flex-none flex items-center gap-2 h-[34px] px-3 rounded-[10px] text-[12.5px] whitespace-nowrap border"
        style={{
          background: p.chingShow ? 'rgba(224,168,46,.16)' : '#fff',
          borderColor: p.chingShow ? 'rgba(224,168,46,.45)' : 'var(--color-ink-line)',
          color: p.chingShow ? 'var(--color-gold-deep)' : 'var(--color-cream-muted)',
          fontWeight: p.chingShow ? 600 : 400,
        }}
        onClick={() => p.onChingShow(!p.chingShow)}
        title={t('แสดง/ซ่อน ตัวหนังสือ ฉิ่ง–ฉับ บนกระดาษ (ทั้งกระดาษไทยและโน้ตสากล) — ไม่เกี่ยวกับเสียง (Ctrl+K)')}
      >
        <span
          className="w-[9px] h-[9px] flex-none rounded-full inline-block"
          style={{
            border: `1.5px solid ${p.chingShow ? '#8a6210' : '#cbbfa8'}`,
            background: p.chingShow ? '#8a6210' : 'transparent',
          }}
        />
        {/* ★ ชื่อปุ่มคงที่ ต่อท้ายด้วยสถานะสั้น ๆ — กล่องกว้างตายตัว ไม่ยืดตามคำ */}
        {p.chingShow ? t('ฉิ่งหน้ากระดาษ เปิด') : t('ฉิ่งหน้ากระดาษ ปิด')}
      </button>

      {/* ★★ ซ้ำท่อน — หัวท่อนบนกระดาษเขียน "(2 เที่ยว)" อยู่แล้ว สิ่งที่ได้ยินต้องตรงกัน
          ของเดิมเล่นรวดเดียวจบไม่ย้อนท่อนเลย · ปิดได้เมื่ออยากไล่ตรวจเร็ว ๆ ท่อนละเที่ยว */}
      <button
        className="w-[124px] flex-none flex items-center gap-2 h-[34px] px-3 rounded-[10px] text-[12.5px] whitespace-nowrap border"
        style={{
          background: p.repeatOn ? 'rgba(224,168,46,.16)' : '#fff',
          borderColor: p.repeatOn ? 'rgba(224,168,46,.45)' : 'var(--color-ink-line)',
          color: p.repeatOn ? 'var(--color-gold-deep)' : 'var(--color-cream-muted)',
          fontWeight: p.repeatOn ? 600 : 400,
        }}
        onClick={() => p.onRepeat(!p.repeatOn)}
        title={t('เล่นซ้ำท่อนตามจำนวนเที่ยวที่เขียนไว้ที่หัวท่อน (Ctrl+R)')}
      >
        <span style={{ fontSize: 13, lineHeight: 1 }}>↻</span>
        {p.repeatOn ? t('ซ้ำท่อน เปิด') : t('ซ้ำท่อน ปิด')}
      </button>

      <div className="flex items-center gap-1.5">
        <span className="text-[12px] text-[var(--color-cream-muted)]">{t('เทียบเสียง')}</span>
        <div className="flex p-[3px] gap-[3px] rounded-[10px] bg-[rgba(42,33,24,.06)]">
          {/* ★ ห้ามตั้งชื่อตัวแปรวนลูปว่า `t` ที่นี่ — มันจะบัง t() ของ i18n
              แล้วบรรทัดที่เผลอเรียก t('…') ข้างในจะพังตอนรัน ไม่ใช่ตอนคอมไพล์ */}
          {TUNING_SYSTEMS.map((sys: any) => {
            const on = p.tuning === sys.id;
            return (
              <button
                key={sys.id}
                className="h-[26px] px-2.5 grid place-items-center rounded-lg text-[12px] whitespace-nowrap"
                style={{
                  fontWeight: on ? 600 : 400,
                  color: on ? '#3a2a08' : 'var(--color-cream-muted)',
                  background: on ? 'linear-gradient(135deg,#f7d778,#e0a82e 55%,#c98a16)' : 'transparent',
                }}
                onClick={() => p.onTuning(sys.id)}
              >
                {tuningLabel(sys)}
              </button>
            );
          })}
        </div>
      </div>

      {/* แถบตำแหน่ง — ลากได้ (seek ตอนปล่อยนิ้ว ไม่ใช่ทุกเฟรม) */}
      <div className="flex-1 flex flex-col gap-1 min-w-[140px]">
        <div
          className="h-1.5 rounded-[3px] bg-[rgba(42,33,24,.1)] relative overflow-hidden cursor-pointer"
          onMouseDown={(e) => {
            const r = e.currentTarget.getBoundingClientRect();
            p.onSeek(Math.max(0, Math.min(1, (e.clientX - r.left) / r.width)));
          }}
        >
          <div
            className="absolute left-0 top-0 bottom-0 rounded-[3px]"
            style={{
              width: `${Math.max(0, Math.min(1, p.progress ?? 0)) * 100}%`,
              background: 'linear-gradient(90deg,#f0c75e,#e0a82e)',
            }}
          />
          {p.sectionMarks.map((m, i) => (
            <div
              key={i}
              className="absolute top-0 bottom-0 w-px bg-[rgba(42,33,24,.18)]"
              style={{ left: `${m.at * 100}%` }}
              title={m.name}
            />
          ))}
        </div>
        <div className="flex justify-between text-[10px] text-[var(--color-cream-dim)]">
          {p.sectionMarks.map((m, i) => <span key={i}>{m.name}</span>)}
        </div>
      </div>

      <div className="flex items-center gap-2 px-3 py-1.5 rounded-[11px] whitespace-nowrap"
        style={{ background: 'rgba(224,168,46,.14)', border: '1px solid rgba(224,168,46,.35)' }}>
        <span className="text-[10px] tracking-[.14em] uppercase text-[var(--color-gold-dark)] font-bold">{t('ตำแหน่ง')}</span>
        <span className="font-bold text-[14px] text-[var(--color-gold-deep)]" style={{ fontFamily: 'var(--font-display)' }}>
          {p.posLabel}
        </span>
      </div>
    </div>
  );
}
