// ════════════════════════════════════════════════════════════════════
//  กระดาษโน้ตเปล่า — สำหรับพิมพ์ไปเขียนด้วยมือ
//
//  ★★ ทำไมต้องมี (เจ้าของสั่ง 2026-07-30): ครูต้องการ "กระดาษตารางเปล่า" ของแต่ละ
//     แบบไปแจกในห้องเรียน/ไปร่างโน้ตด้วยดินสอ — เดิมทำได้แต่ต้องผ่านวิซาร์ดสร้างเพลง
//     เปล่า ๆ ทั้งเพลง แล้วสั่งพิมพ์ = ได้ไฟล์งานที่ไม่ได้ต้องการมาหนึ่งไฟล์
//
//  ★ ใช้ตัววาดตัวเดียวกับกระดาษจริง (ThaiSheet) — ห้ามเขียนตัววาดที่สอง
//    ไม่งั้นกระดาษเปล่ากับกระดาษที่มีโน้ตจะเพี้ยนจากกันเมื่อแก้อย่างใดอย่างหนึ่ง
//  ★ เพลงเปล่าสร้างจาก blankSong ของเอนจิน = ได้ฉิ่ง–ฉับตามอัตราชั้นถูกต้องอยู่แล้ว
//  ★ โชว์แค่ตอนพิมพ์ (.print-only) — บนจอไม่มีอะไรเปลี่ยน
// ════════════════════════════════════════════════════════════════════
import { useMemo } from 'react';
import ThaiSheet from './ThaiSheet';
import { blankSong } from '../../packages/engine/score_templates.mjs';
import { staveCount } from '../../packages/engine/thai_score.mjs';

export type BlankOpts = {
  /** id แม่แบบตาราง (khlui_phiang_o · khong_wong_yai · khim · chakhe) */
  inst: string;
  rate: string;
  lines: number;
  /** เว้นเส้นให้เขียนชื่อเพลง/ผู้เขียนด้วยมือ */
  titleSpace: boolean;
};

export default function BlankSheet({ opts }: { opts: BlankOpts }) {
  const song = useMemo(
    () => blankSong(opts.inst, { rate: opts.rate, sections: 1, lines: opts.lines, bpm: 65 }),
    [opts.inst, opts.rate, opts.lines],
  );
  const nStaves = staveCount(song);

  return (
    <div className="print-only blank-print">
      {opts.titleSpace && (
        /* ★ เส้นประให้เขียนด้วยมือ — ไม่ใช่ช่องกรอกในโปรแกรม
           ขอบเขต: ชื่อเพลง + ผู้เขียน เท่านั้น อย่างอื่นครูเขียนในตารางได้เอง
           ★ เยื้องซ้ายให้ตรงขอบตาราง — ตารางที่มีป้ายชื่อบรรทัดเว้นร่องซ้ายไว้ 58px
             ถ้าไม่เยื้อง เส้นเขียนชื่อเพลงจะเริ่มก่อนตารางแล้วดูเหลื่อมกัน */
        <div className="blank-head" style={{ paddingLeft: nStaves > 1 ? 58 : 4 }}>
          <div className="blank-line blank-line-title">
            <span className="blank-label">ชื่อเพลง</span>
          </div>
          <div className="blank-line">
            <span className="blank-label">ผู้เขียน / ผู้ถอดโน้ต</span>
          </div>
        </div>
      )}
      <ThaiSheet
        song={song}
        twoHands={nStaves === 2}
        sel={null}
        onSelect={() => {}}
        zoom={1}
        followSel={false}
      />
    </div>
  );
}
