// ════════════════════════════════════════════════════════════════════
//  THAI SCORE — ตัวประกอบหน้าจอทั้งแอป
//
//  ★ เมนูบาร์ของระบบยิง event 'menu' มาที่นี่ที่เดียว แล้วส่งต่อให้จอที่เปิดอยู่
//    (Rust ไม่รู้เรื่องโน้ตเลย — มันแค่บอกว่าผู้ใช้กดรายการไหน)
//  ★ เตือนก่อนปิดถ้ายังไม่บันทึก
// ════════════════════════════════════════════════════════════════════
import { useCallback, useEffect, useRef, useState } from 'react';
import { listen } from '@tauri-apps/api/event';
import { invoke } from '@tauri-apps/api/core';
import { getCurrentWindow } from '@tauri-apps/api/window';
import { confirm, message } from '@tauri-apps/plugin-dialog';
import Library, { type Recent } from './screens/Library';
import Wizard from './screens/Wizard';
import Editor from './screens/Editor';
import Activation from './screens/Activation';
import {
  AboutDialog, BlankPaperDialog, BLANK_PAPER_DEFAULT, ExportDialog, GuideDialog,
  KeysDialog, LicenseDialog, PageSetup, PrintDialog, SongInfo, type BlankPaperOpts, type HelpTab,
} from './screens/Dialogs';
import { licenseStatus, type LicenseStatus } from './lib/license';
import { copyFromFocusedField, pasteIntoFocusedField } from './lib/paste-text';
import { setLang, syncLangFromNative, t, useLang } from './lib/i18n';
import { APP_VERSION } from './lib/version';
import BlankSheet from './components/BlankSheet';
import {
  exportMidi, exportMusicXml, exportWebsiteJson, openScore, openScoreAt,
  listPrinters, pdfBackend, printPdf, printToPrinter, printViaSystemDialog, saveScore,
  type Printer,
} from './lib/files';
import { inferRates } from '../packages/engine/thai_score_edit.mjs';
import { canBeWestern } from '../packages/engine/western_score.mjs';
import { DEFAULT_PAGE } from '../packages/engine-ext/thscore_file.mjs';
import { songTitle, type Doc } from './lib/doc';
import './styles/notation.css';

/** ★ เลขรุ่นย้ายไปอยู่ที่ src/lib/version.ts แล้ว (2026-08-05) — ที่นั่นมีคำอธิบาย
 *  ว่าต้องตรงกันกี่ที่ · ตัวส่งออก MusicXML ก็ใช้ค่าเดียวกันนี้ */
const RECENTS_KEY = 'thaiscore.recents';

type Screen = 'library' | 'wizard' | 'editor';

export default function App() {
  // ★ ที่เดียวของทั้งแอปที่ต่อสายกับภาษา — เปลี่ยนภาษาแล้วทุกจอวาดใหม่ตามพ่อ
  //   (ไม่มีคอมโพเนนต์ไหนถูกห่อ React.memo จึงไม่ต้องต่อสายซ้ำที่ลูก)
  useLang();
  const [screen, setScreen] = useState<Screen>('library');
  const [doc, setDoc] = useState<Doc | null>(null);
  const [path, setPath] = useState<string | null>(null);
  const [dirty, setDirty] = useState(false);
  const [recents, setRecents] = useState<Recent[]>(() => {
    try { return JSON.parse(localStorage.getItem(RECENTS_KEY) || '[]'); } catch { return []; }
  });
  const [menuEvent, setMenuEvent] = useState<{ id: string; n: number } | null>(null);
  const [modal, setModal] = useState<null | 'page' | 'export' | 'print' | 'song'>(null);
  /** รายชื่อเครื่องพิมพ์ — อ่านตอนกดพิมพ์ทุกครั้ง (เสียบเครื่องพิมพ์เพิ่มระหว่างใช้งานได้) */
  const [printers, setPrinters] = useState<Printer[]>([]);
  /** ตัวเลือกกระดาษเปล่า · null = กล่องปิดอยู่ */
  const [blank, setBlank] = useState<BlankPaperOpts | null>(null);
  /** แท็บของกล่องช่วยเหลือที่เปิดอยู่ — null = ปิด */
  const [helpTab, setHelpTab] = useState<HelpTab | null>(null);
  /** สถานะลิขสิทธิ์ — null = ยังอ่านไม่เสร็จ (ยังไม่รู้ว่าจะให้เข้าโปรแกรมได้ไหม) */
  const [license, setLicense] = useState<LicenseStatus | null>(null);
  const seq = useRef(0);

  // เก็บค่าล่าสุดไว้ให้ตัวจับ event อ่าน โดยไม่ต้องผูก listener ใหม่ทุกครั้ง
  const live = useRef({ doc, path, dirty, screen, allowed: false });
  live.current = { doc, path, dirty, screen, allowed: !!license?.allowed };

  // ── ด่านลิขสิทธิ์ ───────────────────────────────────────────────
  //  ★ อ่านครั้งเดียวตอนเปิดโปรแกรม — ระหว่างยังไม่รู้ผล **ห้ามวาดหน้าแรก**
  //    ไม่งั้นจะเห็นหน้าแรกแวบหนึ่งแล้วถูกเด้งไปหน้าเปิดใช้งาน (ดูเหมือนพัง)
  //  ★ อ่านไม่ได้เลย (ไม่ควรเกิด) = ปล่อยให้ใช้งานได้ ดีกว่าล็อกคนที่จ่ายเงินแล้ว
  //    ออกจากโปรแกรมของตัวเองเพราะความผิดพลาดของเราเอง
  useEffect(() => {
    licenseStatus()
      .then(setLicense)
      .catch(() => setLicense({
        state: 'unconfigured', machineCode: '', name: '', key: '',
        daysLeft: 0, trialDays: 0, allowed: true, webActivateUrl: '',
      }));
  }, []);

  // ── ภาษา: เอาค่าที่ฝั่งเนทีฟจำไว้เป็นหลัก (ดู syncLangFromNative) ──
  useEffect(() => { void syncLangFromNative(); }, []);

  // ── โหมดตรวจตัวเอง (ดู src-tauri/src/selftest.rs) ────────────────
  //    ไม่ได้ตั้ง env var = คืนค่าว่าง จึงไม่มีผลอะไรกับผู้ใช้จริง
  useEffect(() => {
    // ★★ โหมดตรวจสภาพเครื่อง (smoke) — ใช้ยืนยัน **สถาปัตยกรรมที่เราไม่มีเครื่องจริง**
    //    (Apple Silicon) ผ่านเครื่องของ GitHub · ดู .github/workflows/mac-arm64.yml
    //    ★ ต้องพิสูจน์ว่า "หน้าจอวาดได้จริง" ไม่ใช่แค่หน้าต่างเปิด — วิธีที่เชื่อได้คือ
    //      ให้ **เอนจินโน้ตทำงานจริงหนึ่งรอบ** แล้วรายงานจำนวนที่วาดได้ออกมา
    {
      invoke<boolean>('selftest_is_smoke').then(async (on) => {
        if (!on) return;
        const lines: string[] = [];
        try {
          const { blankSong } = await import('../packages/engine/score_templates.mjs');
          const { fitWestern } = await import('../packages/engine-ext/thscore_file.mjs');
          const song = blankSong('khong_wong_yai', { rate: 'สองชั้น', sections: 1, lines: 2, bpm: 65 });
          const fit = fitWestern(song, { barsPerLine: 6, staffMm: 7, marginMm: 12, orientation: 'portrait' });
          lines.push(`เอนจินโน้ตวาดได้ ${fit.lines} บรรทัด · บรรทัดสูง ${fit.staffMm.toFixed(2)} มม.`);
        } catch (e) {
          lines.push(`⚠ เอนจินโน้ตพัง: ${String(e).slice(0, 200)}`);
        }
        try {
          const ac = new AudioContext();
          lines.push(`ระบบเสียงเปิดได้ที่ ${ac.sampleRate} Hz · สถานะ ${ac.state}`);
          await ac.close();
        } catch (e) {
          lines.push(`⚠ ระบบเสียงเปิดไม่ได้: ${String(e).slice(0, 120)}`);
        }
        // ★ ต้อง **รอให้จอวาดจริง** ก่อนนับ — โค้ดนี้อยู่ใน useEffect ของ App ซึ่งวิ่ง
        //   ตั้งแต่ยังไม่รู้สถานะลิขสิทธิ์ (App คืน null อยู่) ถ้านับทันทีจะได้ 0 ปุ่มเสมอ
        //   แล้ว CI จะฟ้องว่าจอพัง ทั้งที่จอปกติ (เจอตอนลองบนเครื่อง Intel 2026-08-07)
        let btns = 0;
        for (let i = 0; i < 60 && btns === 0; i += 1) {
          btns = document.querySelectorAll('button').length;
          if (btns === 0) await new Promise((r) => setTimeout(r, 100));
        }
        lines.push(btns > 0 ? `หน้าจอวาดเสร็จ ${btns} ปุ่ม` : '⚠ หน้าจอไม่มีปุ่มเลย — อาจวาดไม่สำเร็จ');
        for (const l of lines) invoke('selftest_report', { msg: l }).catch(() => {});
      }).catch(() => {});
    }
    // ── โหมดวัดท่อส่งภาพ (ดู src-tauri/src/framepipe.rs + lib/pipe_bench.ts) ──
    //    งานเตรียมทำตัวอัดคลิป · ไม่ได้ตั้ง env var = ไม่โหลดโมดูลเลย
    invoke<string>('pipe_is_bench').then(async (mode) => {
      if (!mode) return;
      // ★ ธงให้จอเขียนโน้ตรู้ว่าให้เปิดทางหยิบเพลง/ชุดเสียงไปทำคลิป (ดู Editor.tsx)
      (window as any).__clipBench = true;
      const { runPipeBench } = await import('./lib/pipe_bench');
      await runPipeBench(mode);
    }).catch(() => {});

    invoke<{ score: string | null; audio: boolean; clip: string | null; clipSave: string | null; clipSeconds: string | null }>('selftest_config')
      .then(async (cfg) => {
        // ★ ธงให้จอเขียนโน้ตอัดคลิปเองด้วยทางเดินของผู้ใช้จริง (ดู Editor.tsx)
        if (cfg.clip) (window as any).__clipAuto = cfg.clip;
        if (cfg.clipSave) (window as any).__clipAutoSave = cfg.clipSave;
        if (cfg.clipSeconds) (window as any).__clipAutoSeconds = cfg.clipSeconds;
        if (cfg.score) {
          const d = await openScoreAt(cfg.score);
          if (d) { setDoc(d); setPath(cfg.score); setDirty(false); setScreen('editor'); }
        }
        if (cfg.audio) {
          // นับจำนวนเสียงที่ "จองจริง" กับ Web Audio — วิธีเดียวกับที่ใช้พิสูจน์บนเว็บ
          // (ดูจำนวนโหนดที่ start จริง ไม่ใช่เชื่อว่าโค้ดเรียกครบ)
          const proto = (window as any).AudioBufferSourceNode?.prototype;
          if (proto) {
            const orig = proto.start;
            (window as any).__sndCount = 0;
            proto.start = function (...a: any[]) { (window as any).__sndCount++; return orig.apply(this, a); };
          }
        }
      })
      .catch(() => {});
  }, []);

  // ── ชื่อหน้าต่าง + จุดบอกว่ายังไม่บันทึก ──────────────────────────
  useEffect(() => {
    const w = getCurrentWindow();
    const name = doc ? songTitle(doc.song) : t('ยังไม่ตั้งชื่อ');
    w.setTitle(screen === 'editor' ? `${dirty ? '● ' : ''}${name} — THAI SCORE` : 'THAI SCORE')
      .catch(() => {});
  }, [doc?.song?.title, dirty, screen]);

  /**
   * ส่งออก PDF เป็นระบบใดระบบหนึ่ง — **สลับผังบนจอไปที่แบบนั้นจริง ๆ ก่อนพิมพ์**
   *
   * ★★ ทำไมต้องสลับผังจริง ไม่ใช่ยัดค่าชั่วคราว ★★
   *   ตัวที่ตัดสินว่าอะไรจะติดไปบนกระดาษคือ **สิ่งที่ถูกเรนเดอร์อยู่จริง** —
   *   `view.layout` เป็นคนคุมว่าแผงไหนถูก mount · ของที่ไม่อยู่ใน DOM
   *   จะสั่งพิมพ์ยังไงก็ไม่ออก (CSS ซ่อน/แสดงช่วยอะไรไม่ได้เลย)
   *   เจ้าของรายงานอาการครบทุกกรณี 2026-08-07:
   *     อยู่หน้าไทย สั่งสากล → ออกไทย · อยู่หน้าสากล สั่งไทย → ออกสากล
   *     อยู่หน้าแบ่งครึ่ง สั่งอะไรก็ออกทั้งคู่
   *   ★ ของเดิมเคยลองยัด data-print-what ชั่วคราวแล้ว **ใช้ไม่ได้** เพราะ
   *     show_print_ui คืนค่าทันทีที่กล่องพิมพ์เด้ง ยังไม่ทันที่ผู้ใช้กดบันทึก
   *     ค่าก็ถูกคืนกลับไปแล้ว (race ที่มองไม่เห็นและไม่มีอะไรฟ้อง)
   *   → สลับผังจริงแล้วไม่ต้องคืนค่า = ไม่มี race และ **สิ่งที่เห็นบนจอ
   *     คือสิ่งที่ได้ในไฟล์เสมอ** ซึ่งเป็นสิ่งที่ผู้ใช้ตรวจสอบเองได้
   */
  const exportPdfAs = useCallback(async (what: 'thai' | 'western') => {
    const d = live.current.doc;
    if (!d) return;
    const next: Doc = {
      ...d,
      view: { ...d.view, layout: what },
      page: { ...d.page, what },
    };
    setDoc(next);
    // รอให้ React วาดแผงที่ต้องใช้เสร็จก่อน — โน้ตสากลวาดด้วย VexFlow ใน useEffect
    // ถ้าสั่งพิมพ์เร็วกว่านี้จะได้แผงเดิมที่ยังไม่ถูกแทนที่
    await new Promise<void>((r) => requestAnimationFrame(
      () => requestAnimationFrame(() => setTimeout(r, 250)),
    ));
    await printPdf(next);
  }, []);

  const remember = useCallback((p: string, d: Doc) => {
    const rates = inferRates(d.song);
    const r: Recent = {
      path: p,
      title: songTitle(d.song),
      // ★ ชื่อเครื่องดนตรี = ศัพท์ดนตรีไทย ไม่แปล
      instrument: d.song.instrumentTh || (Number(d.song.hands ?? 2) === 2 ? 'ฆ้องวงใหญ่' : 'เครื่องทำนอง'),
      hands: Number(d.song.hands ?? 2),
      hongs: Number(d.song.totalHongs) || 0,
      rate: [...new Set(rates)].join(' · '),
      at: new Date().toISOString(),
    };
    setRecents((old) => {
      const next = [r, ...old.filter((x) => x.path !== p)].slice(0, 12);
      try { localStorage.setItem(RECENTS_KEY, JSON.stringify(next)); } catch { /* โควตาเต็ม */ }
      return next;
    });
  }, []);

  const forget = (p: string) => {
    setRecents((old) => {
      const next = old.filter((x) => x.path !== p);
      try { localStorage.setItem(RECENTS_KEY, JSON.stringify(next)); } catch { /* โควตาเต็ม */ }
      return next;
    });
  };

  const confirmDiscard = useCallback(async () => {
    if (!live.current.dirty) return true;
    return confirm(t('งานที่แก้ไว้จะหายไป ต้องการทิ้งไหม'), {
      title: t('ยังไม่ได้บันทึก'),
      kind: 'warning',
      okLabel: t('ทิ้งแล้วไปต่อ'),
      cancelLabel: t('กลับไปแก้ต่อ'),
    });
  }, []);

  const doSave = useCallback(async (saveAs = false) => {
    const cur = live.current;
    if (!cur.doc) return;
    const p = await saveScore(cur.doc, saveAs ? null : cur.path, APP_VERSION);
    if (p) { setPath(p); setDirty(false); remember(p, cur.doc); }
  }, [remember]);

  const doOpen = useCallback(async () => {
    if (!(await confirmDiscard())) return;
    const r = await openScore();
    if (!r) return;
    setDoc(r.doc); setPath(r.path); setDirty(false); setScreen('editor');
    remember(r.path, r.doc);
  }, [confirmDiscard, remember]);

  const doOpenAt = useCallback(async (p: string) => {
    if (!(await confirmDiscard())) return;
    const d = await openScoreAt(p);
    if (!d) { forget(p); return; }
    setDoc(d); setPath(p); setDirty(false); setScreen('editor');
    remember(p, d);
  }, [confirmDiscard, remember]);

  const doNew = useCallback(async () => {
    if (!(await confirmDiscard())) return;
    setScreen('wizard');
  }, [confirmDiscard]);

  /** ปิดเพลงที่เปิดอยู่ กลับไปหน้าแรก — **ไม่ใช่ปิดโปรแกรม** (เจ้าของขอ 2026-08-06)
   *  ★ ต้องผ่าน `confirmDiscard` เหมือนทางอื่นทุกทาง ไม่งั้นงานที่ยังไม่บันทึกหายเงียบ
   *  ★ ตอนไม่มีเพลงเปิดอยู่ต้องบอกไปตรง ๆ — กฎเดิมของโปรเจกต์:
   *    "เมนูที่กดแล้วไม่เกิดอะไร แย่กว่าไม่มีเมนู" */
  const doClose = useCallback(async () => {
    if (!live.current.doc && live.current.screen === 'library') {
      message(t('ยังไม่มีเพลงที่เปิดอยู่ครับ'), { title: t('ปิดหน้ากระดาษ'), kind: 'info' });
      return;
    }
    if (!(await confirmDiscard())) return;
    setDoc(null); setPath(null); setDirty(false); setScreen('library');
  }, [confirmDiscard]);

  // ── กระดาษโน้ตเปล่า ──────────────────────────────────────────────
  //  ★ ต้องติดธงที่ <html> ก่อนสั่งพิมพ์ เพราะกฎ @media print ใช้ธงนี้ตัดสินว่า
  //    จะพิมพ์ "กระดาษเปล่า" หรือ "เพลงที่เปิดอยู่" — ผู้ใช้กดจากในจอเขียนโน้ตได้
  //  ★ ต้องเอาธงออกทุกทางออก ไม่งั้นครั้งต่อไปที่กดพิมพ์เพลงจะได้กระดาษเปล่าแทน
  //  ★★★ ธงต้องผูกกับ "กล่องเปิดอยู่ไหม" **ห้ามตั้ง-ถอดคร่อมการสั่งพิมพ์** ★★★
  //   เจ้าของรายงาน 2026-08-07: *"กระดาษเปล่ากดแล้วเป็นหน้าเขียนโน้ตทุกอัน"*
  //   ต้นเหตุคือ race ตัวเดียวกับที่จดไว้แล้วที่ exportPdfAs: บน mac
  //   `show_print_ui` **คืนค่าทันทีที่กล่องพิมพ์ของระบบเด้งขึ้น** ยังไม่ทันที่ผู้ใช้
  //   กด "Save as PDF" · ของเดิมถอดธงใน `finally` ธงจึงหลุดก่อนกระดาษจะถูกวาด
  //   → สิ่งที่ออกมาคือ **จอปกติที่เปิดอยู่** (หน้าเขียนโน้ต/หน้าแรก) ทุกครั้ง
  //   ★ ตอนนี้ธงอยู่ตราบเท่าที่กล่องกระดาษเปล่ายังเปิด — ไม่มีอะไรถอดมันกลางคัน
  useEffect(() => {
    const el = document.documentElement;
    if (!blank) return;
    el.setAttribute('data-print-mode', 'blank');
    el.setAttribute('data-blank-nonum', blank.numbers ? '0' : '1');
    el.setAttribute('data-blank-noching', blank.ching ? '0' : '1');
    return () => {
      el.removeAttribute('data-print-mode');
      el.removeAttribute('data-blank-nonum');
      el.removeAttribute('data-blank-noching');
    };
  }, [blank]);

  const printBlank = useCallback(async (o: BlankPaperOpts, asPdf: boolean) => {
    // กระดาษเปล่าใช้ค่าหน้ากระดาษของเอกสารที่เปิดอยู่ ถ้าไม่มีก็ใช้ค่าตั้งต้น
    // ★ what: 'thai' เสมอ — กระดาษเปล่าเป็นตารางไทย ถ้าเอกสารที่เปิดอยู่ค้างไว้ที่
    //   'western' (จากการส่งออก PDF สากลครั้งก่อน) กฎ data-print-what จะซ่อนทิ้งหมด
    const page = { ...(live.current.doc?.page ?? (DEFAULT_PAGE as any)), what: 'thai' };
    const fake = { page } as Doc;
    if (asPdf) {
      const backend = await pdfBackend();
      await printPdf(fake);
      // ★ ทางที่ไม่เงียบ (mac) กล่องของระบบยังเปิดค้างอยู่ตอนนี้ — **ห้ามปิดกล่องนี้**
      //   เพราะกล่องนี้คือสิ่งที่ถือธงกระดาษเปล่าไว้ ปิดแล้วกระดาษจะกลายเป็นจอปกติ
      if (backend.silent) setBlank(null);
      return;
    }
    const list = await listPrinters();
    if (!list.length) {
      await message(t('ไม่พบเครื่องพิมพ์ในเครื่องนี้ — ใช้ "บันทึกเป็น PDF" แทนได้'), {
        title: t('ไม่มีเครื่องพิมพ์'), kind: 'info',
      });
      return;
    }
    const def = list.find((p) => p.isDefault) || list[0];
    try {
      await printToPrinter(fake, def.name, 1);
      setBlank(null);
    } catch (err) {
      await message(String(err), { title: t('พิมพ์ไม่สำเร็จ'), kind: 'error' });
    }
  }, []);

  // ── เปิดกล่องพิมพ์ของเราเอง ──────────────────────────────────────
  //  ★ อ่านรายชื่อเครื่องพิมพ์ใหม่ทุกครั้งที่กด — ผู้ใช้เสียบเครื่องพิมพ์เพิ่มกลางทางได้
  //  ★ ห้ามเปิดกล่องพิมพ์ของตัวแสดงผลเป็นทางหลัก (มันแปะวันที่/ชื่อโปรแกรม/ที่อยู่หน้า
  //    ลงบนกระดาษ สั่งปิดจากโค้ดไม่ได้) — ดู src-tauri/src/printing.rs
  const openPrint = useCallback(async () => {
    if (!live.current.doc) return;
    setPrinters(await listPrinters());
    setModal('print');
  }, []);

  // ── ปิดโปรแกรม — ทางออกทางเดียวของทั้งแอป ────────────────────────
  //  ★★ ห้ามมีทางปิดโปรแกรมที่ไม่ผ่าน requestExit ★★
  //   เดิมมีสองทางที่ทำงานคนละแบบ และ **พังทั้งคู่** (เจ้าของจับได้ 2026-07-30):
  //   · ปุ่มกากบาท → `w.destroy()` ถูกปฏิเสธเพราะ capabilities ไม่มี
  //     `core:window:allow-destroy` · เรียกใน setTimeout ที่ไม่มีตัวรับ error
  //     → **ตอบว่า "ปิดโดยไม่บันทึก" แล้วโปรแกรมไม่ปิด และไม่มีอะไรฟ้องเลย**
  //   · เมนูไฟล์ → `PredefinedMenuItem::quit` ยิง `PostQuitMessage(0)` เข้า
  //     message loop ของ Windows ตรง ๆ **ไม่ผ่าน CloseRequested** = ปิดทันที
  //     ทับงานที่ยังไม่บันทึกโดยไม่เตือน (อันตรายกว่าข้อแรก) → เปลี่ยนเป็นรายการ
  //     ของเราเอง (`file.exit` ใน menu.rs) ที่มาลงที่ฟังก์ชันนี้เหมือนกัน
  //  ★ ถ้า destroy ล้มอีก ต้อง **บอกผู้ใช้** ห้ามเงียบ — ทางหนีสุดท้ายคือถ้าฝั่ง
  //    หน้าจอตายจนไม่ได้ลงทะเบียน onCloseRequested ปุ่มกากบาทจะปิดเองตามปกติ
  //  ★ ต้องประกาศ **ก่อน** ตัวรับเมนู เพราะชื่อนี้ไปอยู่ในลิสต์ deps ของ useEffect
  //    ซึ่งถูกอ่านตอน render (ประกาศทีหลัง = ReferenceError ทั้งแอปตั้งแต่เปิด)
  const requestExit = useCallback(async () => {
    if (live.current.dirty) {
      const ok = await confirm(t('มีการแก้ไขที่ยังไม่ได้บันทึก ถ้าปิดตอนนี้จะหายไป'), {
        title: t('ยังไม่ได้บันทึก "{name}"', { name: live.current.doc ? songTitle(live.current.doc.song) : t('โน้ต') }),
        kind: 'warning',
        okLabel: t('ปิดโดยไม่บันทึก'),
        cancelLabel: t('กลับไปแก้ต่อ'),
      });
      if (!ok) return;
      setDirty(false);
    }
    try {
      await getCurrentWindow().destroy();
    } catch (err) {
      await message(t('ปิดโปรแกรมไม่สำเร็จ: {err}', { err: String(err) }), {
        title: t('ปิดโปรแกรมไม่ได้'), kind: 'error',
      });
    }
  }, []);

  // ── F1 = วิธีใช้ ────────────────────────────────────────────────
  //  ★ ตารางคีย์ลัดในเมนูโฆษณา F1 ไว้ แต่ **กดแล้วไม่เกิดอะไรเลย** (เจ้าของจับได้
  //    2026-07-30) — คีย์ลัดที่ผูกไว้กับรายการเมนูของระบบไม่ได้ถูกเรียก เพราะโฟกัส
  //    คีย์บอร์ดอยู่ในพื้นที่แสดงหน้าจอ ปุ่มจึงไม่เดินไปถึงตารางคีย์ลัดของหน้าต่าง
  //    → ต้องดักที่ฝั่งหน้าจอเองเสมอ (ที่นี่) ป้ายในเมนูเก็บไว้เป็นตัวบอกผู้ใช้เท่านั้น
  //  ★ ผูกกับ e.code ตามกฎของโปรเจกต์ (รอดจากการสลับเป็นแป้นไทย)
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      // ★★ บน Mac ปุ่ม F1 ค่าปริยายเป็น "ปุ่มสื่อ" (หรี่จอ) — ระบบกินไปก่อน แอปไม่เคย
      //   ได้รับ นอกจากผู้ใช้กด fn ค้าง · คู่มือโฆษณา F1 ไว้แต่กดแล้วไม่เกิดอะไร =
      //   ชนกฎเดิมของโปรเจกต์ "เมนูที่กดแล้วไม่เกิดอะไร แย่กว่าไม่มีเมนู" (เจอ 2026-08-17)
      //   → รับ **⌘?** (⌘⇧/) ด้วย ซึ่งเป็นปุ่มช่วยเหลือมาตรฐานของ macOS ทุกโปรแกรม
      //   ★ ผูกกับ e.code ('Slash') ตามกฎ — รอดจากการสลับเป็นแป้นไทย และ "/" ไม่ใช่
      //     ตัวอักษร จึงไม่ชนกฎห้ามใช้ Shift+ตัวอักษร
      const help = e.code === 'F1'
        || ((e.metaKey || e.ctrlKey) && e.shiftKey && e.code === 'Slash');
      if (!help) return;
      e.preventDefault();
      setHelpTab((cur) => (cur === 'guide' ? null : 'guide'));
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  useEffect(() => {
    const un = getCurrentWindow().onCloseRequested(async (e) => {
      if (!live.current.dirty) return;   // ไม่มีอะไรค้าง = ปล่อยให้ปิดตามปกติ
      e.preventDefault();
      await requestExit();
    });
    return () => { un.then((f) => f()); };
  }, [requestExit]);

  // ── เมนูบาร์ของระบบ ─────────────────────────────────────────────
  useEffect(() => {
    const un = listen<string>('menu', (e) => {
      const id = e.payload;
      // ★★ "วาง" ตอนที่เคอร์เซอร์อยู่ในช่องพิมพ์ = วาง **ข้อความ** เสมอ ★★
      //   บน mac รายการเมนูนี้จอง ⌘V ไว้ และคีย์ลัดของแถบเมนูถูกตรวจ *ก่อน*
      //   หน้าต่างที่โฟกัสอยู่ → ตัวแสดงผลไม่เคยได้เห็น ⌘V เลย คัดลอกเนื้อร้อง
      //   จากข้างนอกมาวางในโปรแกรมจึงไม่ได้ (ลูกค้าแจ้ง 2026-08-07)
      //   ★ ต้องดักก่อนด่านเปิดใช้งาน — ช่องใส่ใบลิขสิทธิ์ก็เป็นช่องที่ต้องวางเหมือนกัน
      //   ★ ไม่ได้อยู่ในช่องพิมพ์ = คืน false → ตกไปที่ 'วางทับตรงที่เลือก' ของเดิมทุกอย่าง
      if (id === 'edit.paste' && pasteIntoFocusedField()) return;
      // ★★ ⌘C โดนแบบเดียวกัน — รายการ "คัดลอกห้องนี้" จองไว้ ★★
      //   เจ้าของเจอเองต่อจาก ⌘V (2026-08-07): "คัดลอกข้างในโปรแกรมแล้ววาง
      //   ข้างในโปรแกรมไม่ได้" เพราะ ⌘C ในช่องเนื้อร้องไปคัดลอก *ห้อง* แทน
      //   คลิปบอร์ดของระบบจึงค้างของเก่า พอกดวางก็ได้ของเก่ากลับมา
      //   ★ "คัดลอกบรรทัดนี้" (⌘⇧C) ก็ดักด้วย — อยู่ในช่องพิมพ์แล้วต้องเป็นข้อความเสมอ
      if ((id === 'edit.copyHong' || id === 'edit.copyLine') && copyFromFocusedField()) return;
      // ★ ระหว่างอยู่ในด่านเปิดใช้งาน เมนูบาร์ของระบบยังกดได้อยู่ (ซ่อนไม่ได้) —
      //   ปล่อยผ่านแค่หมวดช่วยเหลือ **กับหมวดภาษา** ที่เหลือต้องตายสนิท ไม่งั้น
      //   สร้าง/เปิดไฟล์ผ่านเมนูได้ทั้งที่ยังไม่ได้เปิดใช้งาน (ด่านที่วาดบนจอไม่ใช่ด่านจริง)
      //   ★ ภาษาต้องเปลี่ยนได้ตั้งแต่ยังไม่เปิดใช้งาน — ไม่งั้นคนที่อ่านไทยไม่ออก
      //     จะติดอยู่ที่หน้ากรอกรหัสภาษาไทยโดยไม่มีทางออก
      if (!live.current.allowed && !id.startsWith('help.') && !id.startsWith('lang.')) return;
      switch (id) {
        case 'lang.th': setLang('th'); return;
        case 'lang.en': setLang('en'); return;
        case 'file.new': doNew(); return;
        case 'file.open': doOpen(); return;
        case 'file.close': doClose(); return;
        case 'file.save': doSave(false); return;
        case 'file.saveAs': doSave(true); return;
        case 'file.pageSetup': setModal('page'); return;
        case 'file.songInfo': if (live.current.doc) setModal('song'); return;
        // ★ ต้องผ่าน requestExit เท่านั้น — ของสำเร็จรูป quit ข้ามด่านเตือนทั้งหมด
        case 'file.exit': requestExit(); return;
        case 'file.print': openPrint(); return;
        case 'file.blankPaper': setBlank(BLANK_PAPER_DEFAULT); return;
        // ★★ "ส่งออก" บนแถบเมนูเป็นรายการเดียว กดแล้วเปิดกล่องรวมทุกรูปแบบ
        //   (เจ้าของสั่ง 2026-07-31: เมนูย่อย 4 รายการเดิม "ไม่สวยและซ้ำซ้อนกับกล่อง")
        //   ★ ตัวสั่งส่งออกจริงอยู่ที่ปุ่มในกล่อง (ดู ExportDialog ข้างล่าง) —
        //     ไม่มี case export.pdf/musicxml/midi/json อีกแล้ว เพราะไม่มีเมนูไหนยิงมา
        //   ★ ตอนอยู่หน้าแรกยังไม่มีเพลง — ต้องบอกไปตรง ๆ ห้ามเงียบ
        //     ("เมนูที่กดแล้วไม่เกิดอะไร แย่กว่าไม่มีเมนู" — กฎเดิมของโปรเจกต์)
        case 'export.dialog':
          if (live.current.doc) setModal('export');
          else {
            message(t('ยังไม่มีเพลงที่เปิดอยู่ — กด "เขียนโน้ตใหม่" หรือ "เปิดไฟล์" ก่อน แล้วค่อยส่งออกครับ'), {
              title: t('ส่งออกไฟล์'), kind: 'info',
            });
          }
          return;
        case 'help.guide': setHelpTab('guide'); return;
        case 'help.keys': setHelpTab('keys'); return;
        case 'help.license': setHelpTab('license'); return;
        case 'help.about': setHelpTab('about'); return;
        default:
          // ที่เหลือเป็นเรื่องของจอเขียนโน้ต — ส่งต่อไปให้มันจัดการ
          seq.current += 1;
          setMenuEvent({ id, n: seq.current });
      }
    });
    return () => { un.then((f) => f()); };
  }, [doNew, doOpen, doClose, doSave, requestExit, openPrint]);

  // ── ★★ ทางลัดของ "ตัวแสดงผล" ที่ต้องแย่งมาทำเอง ─────────────────────
  //  เจ้าของทัก 2026-07-30: "สั่งปริ้นยังกลายเป็นการ save ไฟล์ pdf ไม่ใช่ปริ้นเข้าเครื่อง"
  //  ต้นเหตุที่แท้จริงคือ **Ctrl+P ไม่เคยเป็นของเราเลย** — คีย์ลัดที่ผูกไว้กับรายการ
  //  เมนูของระบบไม่ถูกเรียกเมื่อโฟกัสอยู่ในพื้นที่แสดงผล (เจอมาแล้วกับ F1) แล้ว
  //  **ตัวแสดงผลมีกล่องพิมพ์ของตัวเองบน Ctrl+P ซึ่งค่าตั้งต้นคือ "บันทึกเป็น PDF"**
  //  → กดแล้วได้กล่องเซฟไฟล์ทุกครั้ง ทั้งที่โปรแกรมมีทางพิมพ์ออกกระดาษอยู่แล้ว
  //  ★ ต้องดักที่ฝั่งหน้าจอ + preventDefault เพื่อ **ปิดกล่องของตัวแสดงผลถาวร**
  //    (Ctrl+S ก็เหมือนกัน ของตัวแสดงผลคือ "บันทึกหน้าเว็บ" ซึ่งไม่ใช่การบันทึกเพลง)
  //  ★ ดักที่ระดับ window ของ App ไม่ใช่ในจอเขียนโน้ต เพราะจอนั้นมีเงื่อนไข
  //    "ต้องเลือกช่องอยู่ก่อน" — กดพิมพ์ตอนยังไม่เลือกช่องต้องได้เหมือนกัน
  //  ★★ ทางลัดหมวดไฟล์ทั้งหมดต้องดักเองที่นี่ ★★
  //  ตรวจ 2026-07-31 ก่อนเปิดขาย: เมนูโฆษณา Ctrl+N / Ctrl+O / Ctrl+Alt+S / Ctrl+Q ไว้
  //  แต่ **ไม่มีตัวไหนกดติดเลย** ด้วยเหตุผลเดียวกับ F1 กับ Ctrl+P — คีย์ลัดที่ผูกกับรายการ
  //  เมนูของระบบไม่ถูกเรียกเมื่อโฟกัสคีย์บอร์ดอยู่ในพื้นที่แสดงผล ซึ่งเป็นตลอดเวลาที่ใช้งานจริง
  //  → ต้องดักที่ฝั่งหน้าจอเองทุกตัว · ป้ายในเมนูเก็บไว้เป็นตัวบอกผู้ใช้เท่านั้น
  //  ★ ทุกตัวผูกกับ e.code ตามกฎของโปรเจกต์ (รอดจากการสลับเป็นแป้นไทย)
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (!(e.ctrlKey || e.metaKey)) return;
      // ★ Ctrl+Alt+S = บันทึกเป็น… (ตัวเดียวในชุดนี้ที่ใช้ Alt ร่วม จึงต้องเช็กก่อน)
      if (e.altKey) {
        if (e.code === 'KeyS' && live.current.doc) { e.preventDefault(); doSave(true); }
        return;
      }
      switch (e.code) {
        case 'KeyP': e.preventDefault(); if (live.current.doc) openPrint(); return;
        case 'KeyS': if (e.shiftKey) return; e.preventDefault(); if (live.current.doc) doSave(false); return;
        case 'KeyN': e.preventDefault(); doNew(); return;
        case 'KeyO': e.preventDefault(); doOpen(); return;
        // ★ ปิดหน้ากระดาษ (กลับหน้าแรก) — ต้อง preventDefault ด้วย ไม่งั้นตัวแสดงผล
        //   ตีความ Ctrl+W เป็น "ปิดหน้าต่าง" ซึ่งข้ามด่านเตือน "ยังไม่ได้บันทึก"
        case 'KeyW': e.preventDefault(); doClose(); return;
        case 'KeyQ': e.preventDefault(); requestExit(); return;
        default: return;
      }
    };
    window.addEventListener('keydown', onKey, true);   // capture — ชิงก่อนตัวอื่น
    return () => window.removeEventListener('keydown', onKey, true);
  }, [openPrint, doSave, doNew, doOpen, doClose, requestExit]);

  // ── ลากไฟล์มาวาง ───────────────────────────────────────────────
  useEffect(() => {
    const w = getCurrentWindow();
    const un = w.onDragDropEvent((e) => {
      if (e.payload.type !== 'drop') return;
      if (!live.current.allowed) return;   // ด่านเปิดใช้งาน: ลากไฟล์มาวางก็ต้องไม่เปิด
      const f = e.payload.paths?.[0];
      if (f && /\.(thscore|json)$/i.test(f)) doOpenAt(f);
    });
    return () => { un.then((f) => f()); };
  }, [doOpenAt]);

  /* ★ 3 รายการในเมนูช่วยเหลือ = 3 กล่องแยกกัน (เจ้าของสั่งให้แยก ห้ามยุบเป็นแท็บ)
       + กล่องลิขสิทธิ์ ซึ่งต้องเปิดได้ทั้งในด่านเปิดใช้งานและตอนใช้งานปกติ */
  const helpDialogs = (
    <>
      {helpTab === 'guide' && <GuideDialog onClose={() => setHelpTab(null)} />}
      {helpTab === 'keys' && <KeysDialog onClose={() => setHelpTab(null)} />}
      {helpTab === 'license' && license && (
        <LicenseDialog status={license} onChange={setLicense} onClose={() => setHelpTab(null)} />
      )}
      {helpTab === 'about' && <AboutDialog onClose={() => setHelpTab(null)} version={APP_VERSION} />}
    </>
  );

  // ★ ยังอ่านสถานะลิขสิทธิ์ไม่เสร็จ — ห้ามวาดหน้าแรกแวบหนึ่งแล้วเด้งไปด่าน
  if (!license) return null;

  // ★★ ด่านลิขสิทธิ์: ยังไม่เริ่มทดลองใช้ หรือครบ 3 วันแล้ว = เข้าโปรแกรมไม่ได้เลย
  //    (คำสั่งเจ้าของ 2026-07-30 — ล็อกสนิท ไม่ใช่โหมดจำกัดความสามารถ)
  if (!license.allowed) {
    return (
      <>
        <Activation status={license} onChange={setLicense} />
        {helpDialogs}
      </>
    );
  }

  return (
    <>
      {screen === 'library' && (
        <Library
          recents={recents}
          trial={license.state === 'trial' ? license.daysLeft : null}
          onLicense={() => setHelpTab('license')}
          onNew={doNew}
          onOpen={doOpen}
          onOpenAt={doOpenAt}
          onForget={forget}
          onBlankPaper={() => setBlank(BLANK_PAPER_DEFAULT)}
        />
      )}

      {screen === 'wizard' && (
        <Wizard
          onCancel={() => setScreen(doc ? 'editor' : 'library')}
          onCreate={(d) => { setDoc(d); setPath(null); setDirty(true); setScreen('editor'); }}
        />
      )}

      {screen === 'editor' && doc && (
        <Editor
          doc={doc}
          onChange={setDoc}
          onDirty={() => setDirty(true)}
          menuEvent={menuEvent}
          onHome={doClose}
          onExport={() => setModal('export')}
          onSongInfo={() => setModal('song')}
        />
      )}

      {/* ★ รายละเอียดเพลง — ข้อความล้วนที่ผู้ใช้กรอกเอง + ติ๊กว่าอะไรขึ้นหัวกระดาษ
          แก้ song (ข้อมูลเพลง) กับ page.head (เรื่องของกระดาษ) คนละก้อนโดยตั้งใจ */}
      {modal === 'song' && doc && (
        <SongInfo
          song={doc.song}
          page={doc.page}
          onSong={(patch) => { setDoc({ ...doc, song: { ...doc.song, ...patch } }); setDirty(true); }}
          onPage={(p) => { setDoc({ ...doc, page: p }); setDirty(true); }}
          onClose={() => setModal(null)}
        />
      )}

      {modal === 'page' && doc && (
        <PageSetup
          page={doc.page}
          /* ★ ต้องส่งเพลงเข้าไปด้วย — กล่องนี้บอก "จะได้จริงกี่ มม. กี่บรรทัด กี่หน้า"
             ซึ่งวัดจากตัววาดจริงกับเพลงจริง ไม่ใช่จากสูตรประมาณ (fitWestern) */
          song={doc.song}
          onChange={(p) => { setDoc({ ...doc, page: p }); setDirty(true); }}
          onClose={() => setModal(null)}
          onPrint={() => openPrint()}
        />
      )}
      {modal === 'export' && doc && (
        <ExportDialog
          onClose={() => setModal(null)}
          /* ★ ส่งออก PDF ต้องเลือกทีละแบบ (ดูเหตุผลที่ ExportDialog)
             — ยัด page.what ชั่วคราวให้ตรงกับที่เลือก ไม่แตะค่าที่ผู้ใช้ตั้งไว้จริง
               เพราะนี่คือ "รูปแบบของไฟล์ที่ส่งออกครั้งนี้" ไม่ใช่การตั้งค่าถาวร */
          onPdf={(what) => exportPdfAs(what)}
          hasWestern={canBeWestern(doc.song)}
          onMusicXml={() => exportMusicXml(doc)}
          onMidi={() => exportMidi(doc)}
          onJson={() => exportWebsiteJson(doc)}
          /* ★ ตัวอัดคลิปอยู่ในหน้าเขียนโน้ต เพราะต้องใช้ **กระดาษที่อยู่บนจอจริง**
             กับชุดเสียงที่กำลังใช้อยู่ — ส่งต่อผ่านช่องเดียวกับเมนูบาร์ จึงมีตัวรับที่เดียว */
          onClip={() => { setModal(null); setMenuEvent((m) => ({ id: 'export.clip', n: (m?.n || 0) + 1 })); }}
        />
      )}
      {/* ★ 3 รายการในเมนูช่วยเหลือเปิดกล่องเดียวกัน แต่ **คนละแท็บ** —
          ของเดิมทั้งสามเปิดหน้าเดียวกันเป๊ะ (เจ้าของจับได้ 2026-07-30) */}
      {blank && (
        <>
          <BlankPaperDialog
            opts={blank}
            onChange={setBlank}
            onClose={() => setBlank(null)}
            onPrint={() => printBlank(blank, false)}
            onPdf={() => printBlank(blank, true)}
          />
          {/* ★ แผ่นกระดาษเปล่าต้องอยู่ใน DOM จริงตอนสั่งพิมพ์ (display:none ไม่พิมพ์)
              → ใช้คลาส .print-only ซ่อนบนจอแต่โผล่ตอนพิมพ์ */}
          <BlankSheet opts={{ inst: blank.inst, rate: blank.rate, lines: blank.lines, titleSpace: blank.titleSpace }} />
        </>
      )}
      {modal === 'print' && doc && (
        <PrintDialog
          printers={printers}
          page={doc.page}
          onClose={() => setModal(null)}
          onPageSetup={() => setModal('page')}
          onSystemDialog={() => { setModal(null); printViaSystemDialog(doc); }}
          onPrint={async (printer, copies) => {
            setModal(null);
            try {
              await printToPrinter(doc, printer, copies);
            } catch (err) {
              await message(String(err), { title: t('พิมพ์ไม่สำเร็จ'), kind: 'error' });
            }
          }}
        />
      )}
      {helpDialogs}
    </>
  );
}
