// ════════════════════════════════════════════════════════════════════
//  ชุดเสียงโน้ตไทย — FORK ของ website/src/lib/score_sound_bank.mjs
//
//  ── ต่างจากต้นฉบับ 3 อย่าง ทั้งหมดเพราะ "แอปเดสก์ท็อปไม่ใช่เว็บ" ─────────
//   1 ลำดับนามสกุลไฟล์มาจาก pack.exts (m4a/mp3 ก่อน ogg) — WKWebView ของ macOS
//     ถอดรหัส .ogg ไม่ได้ · ต้นฉบับ probe จาก <audio> ซึ่งเชื่อถือได้บนเว็บ
//     แต่ในแอปเรารู้ล่วงหน้าอยู่แล้วว่าจะรันบน engine ไหน
//   2 ตัด `?v=SAMPLE_VERSION` ทิ้งทุก URL — ไม่มี CDN ให้เจาะแคช
//   3 URL ของฉิ่งรับมาทาง pack.chingBase ได้ (ต้นฉบับ hardcode '/audio/ching/')
//     ★ ข้อนี้คือตัวแรกที่ควร backport กลับเข้าเว็บ แล้วไฟล์นี้จะเหลือต่างแค่ 2 ข้อ
//   4 **โวลุ่มแยกเครื่องดนตรี / ฉิ่ง–ฉับ + ปิดเสียงแยกกัน** (ลูกค้าขอ 2026-08-16)
//     เสียงทุกเส้นวิ่งผ่าน "บัส" สองเส้น (busInst · busChing) แทนที่จะต่อตรงเข้า
//     ปลายทาง — ดูเหตุผลที่ ensureCtx ข้างล่าง (สรุป: ตัวจองเสียงจองล่วงหน้า 2 วิ
//     ปรับที่ตัวโน้ตทีละตัวจะหน่วง 2 วินาทีทุกครั้งที่เลื่อนสไลเดอร์)
//   5 **เลื่อนเสียงทั้งเพลงกับชุดแซมเปิล** (เจ้าของสั่ง 2026-08-16) — ดู pickSample
//     ฆ้องวงยืม "ลูกยอด/ลูกท้าย" มาดัดเสียงแทนลูกที่ไม่มี
//   6 **ปลุกระบบเสียงหลังเครื่อง/จอพัก** (เจ้าของเจอเอง 2026-08-18) — ดู wakeCtx
//     WKWebView ของ macOS พัก AudioContext ด้วยสถานะ **'interrupted'** ซึ่งไม่ได้
//     อยู่ในมาตรฐาน · เว็บบนเบราว์เซอร์ทั่วไปไม่เจอข้อนี้ จึงเป็นของเดสก์ท็อปแท้ ๆ
//
//  ★★ ทุกอย่างที่เหลือต้องเหมือนต้นฉบับเป๊ะ โดยเฉพาะ:
//     · look-ahead scheduler (LOOKAHEAD 2.0 วิ / เติมคิวทุก 250 ms)
//       — ของเดิมจองเสียงทั้งเพลงทีเดียว เชิดจีน 5,693 node ทำเธรดเสียงล้น
//         เสียงหายจริง 9.15 วินาที วัดด้วย WASAPI loopback
//     · `start()` ต้องมาก่อน `stop()` เสมอ — สลับลำดับ = Web Audio โยน exception
//       แล้วเพลงเงียบสนิททั้งเพลงโดยไม่มีอะไรฟ้อง
//     · sort ตามเวลาก่อนเดินตัวชี้ ni/ci — ไฟล์ที่เรียงมาไม่ครบจะหล่นหายเงียบ ๆ
// ════════════════════════════════════════════════════════════════════
import { tuningRatio, isTuning, noteHz } from '../../packages/engine/thai_tuning.mjs';
import { marimbaStrike } from '../../packages/engine/marimba.mjs';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export function createSoundBank(pack) {
  let ctx = null;
  let bank = null;        // [AudioBuffer|null]
  let loading = null;
  let ching = null;       // [ฉิ่ง, ฉับ]
  let live = [];          // ต้นเสียงที่ตั้งเวลาไว้แล้ว (เก็บไว้ให้ "หยุด" ได้จริง)

  // 'banks' (ฆ้องวง) = ไฟล์อัดจริงแยกโฟลเดอร์ครบสามระบบ → สลับระบบต้องโหลดใหม่
  // 'ratio' (เครื่องทำนอง) = ชุดเดียว → สลับระบบแค่เปลี่ยนอัตราเร่งตอนเล่น
  const BANKS_MODE = pack.tuning === 'banks';
  // ★★ โหมดสังเคราะห์ (2026-07-30) — ไม่มีแซมเปิลเลย ปั้นคลื่นเสียงเอง
  //   ดูเหตุผลเต็ม ๆ ที่ packages/engine/marimba.mjs (ยกมาจากเว็บทั้งดุ้น)
  const SYNTH = pack.synth || '';
  let system = 'chromatic';
  let bankSystem = '';

  const EXTS = pack.exts && pack.exts.length ? pack.exts : [pack.fallbackExt || 'mp3', 'ogg'];
  const CHING_BASE = pack.chingBase || '/audio/ching';

  const noteUrl = (i, ext) =>
    `${pack.base}${BANKS_MODE ? `/${system}` : ''}/${pack.file}_${String(i).padStart(2, '0')}.${ext}`;

  // ── เลื่อนเสียงทั้งเพลงกับ "เสียงที่อัดมาจริง" ──────────────────────
  //  `pack.midi`     = เสียงที่ **ควรได้ยิน** (ผังของเพลง · เลื่อนแล้ว)
  //  `pack.baseMidi` = เสียงที่ **ไฟล์อัดไว้จริง** (ผังก่อนเลื่อน)
  //  เท่ากันเมื่อไร = ไม่ได้เลื่อน → ทุกอย่างเหมือนเดิมเป๊ะทุกบรรทัด
  const BASE = Array.isArray(pack.baseMidi) && pack.baseMidi.length ? pack.baseMidi : (pack.midi || []);

  /**
   * ★★ เลือกไฟล์เสียง + อัตราเร่ง สำหรับโน้ตลำดับที่ i ★★
   *
   *  เจ้าของสั่ง 2026-08-16: *"เสียงที่เกินจากฆ้องมา ให้ใช้ลูกยอดและลูกท้ายของฆ้อง
   *  มาปรับเสียงขึ้นหรือลง ใช้ทดแทนเสียงที่ขาดไป"*
   *
   *  ทำได้ด้วยกฎข้อเดียว: **หาลูกที่เสียงใกล้เป้าที่สุด แล้วดัดส่วนต่าง**
   *   · เลื่อนเป็นขั้นเสียงไทย เสียงส่วนใหญ่จะไปตกลูกฆ้องจริงพอดี (ส่วนต่าง = 0
   *     → ได้ยินลูกฆ้องจริง ไม่ถูกดัดเลย)
   *   · ตัวที่ล้นปลายวง ลูกที่ใกล้ที่สุดคือ **ลูกยอด** (บนสุด) หรือ **ลูกท้าย**
   *     (ล่างสุด) โดยอัตโนมัติ — ไม่ต้องเขียนกรณีพิเศษ
   *  ★ ไม่ได้เลื่อน (ปกติ) = ทางลัดบรรทัดแรก คืน {i, 1} ทันที เร็วเท่าเดิม
   */
  function pickSample(i) {
    const want = pack.midi?.[i];
    const mine = BASE[i];
    if (want == null || mine == null || want === mine) return { j: i, semis: 0 };
    let j = i; let best = Infinity;
    for (let k = 0; k < BASE.length; k += 1) {
      const m = BASE[k];
      if (m == null) continue;
      const d = Math.abs(m - want);
      if (d < best) { best = d; j = k; if (!d) break; }
    }
    return { j, semis: want - BASE[j] };
  }

  /** อัตราเร่งเสียงของโน้ตลำดับที่ i ตามระบบที่เลือก + ส่วนต่างที่ต้องดัด
   *  ★ โหมด banks ไม่คูณอัตราเทียบเสียงซ้ำ — ไฟล์ถูกจูนมาแล้ว คูณซ้ำเพี้ยนสองต่อ
   *    (แต่ส่วนต่างจากการเลื่อนเสียงต้องคูณ ไม่งั้นเลื่อนแล้วไม่ได้ยินอะไรเปลี่ยน)
   *
   *  ★★ ลูกที่ยืมมาดัด **ต้องดัดตามระบบเทียบเสียงที่เปิดอยู่** ★★
   *   เจ้าของสั่ง 2026-08-16: *"ถ้าเลือกเสียงไทยพระราชทานหรือกรมศิลป์ ก็ให้เลื่อนไป
   *   ตรง ๆ ไม่มีครึ่งเสียง"* — ขั้นเสียงไทยไม่เท่ากับครึ่งเสียงสากล (ไทยขั้นละ
   *   ~171 เซนต์ · สากล 100/200) ดัดด้วยสูตรสากลจะเพี้ยนจากขั้นของระบบไทยราว
   *   28 เซนต์ ซึ่งคนเล่นดนตรีไทยได้ยินออก
   *   → ใช้ **ตารางความถี่ของระบบนั้นเอง** เป็นตัวหารตัวตั้ง (noteHz) แล้วผลลัพธ์
   *     จะตกบนขั้นของระบบนั้นพอดีทุกระบบ · ระบบสากลได้ค่าเท่ากับสูตรเดิมเป๊ะ */
  const rateOf = (i, semis) => {
    if (!semis) return BANKS_MODE ? 1 : tuningRatio(pack.midi?.[i], system);
    const want = pack.midi?.[i];
    if (BANKS_MODE) {
      const from = want - semis;                 // ระดับเสียงที่ลูกที่ยืมมาอัดไว้
      const a = noteHz(want, system);
      const b = noteHz(from, system);
      return a && b ? a / b : Math.pow(2, semis / 12);
    }
    return Math.pow(2, semis / 12) * tuningRatio(want, system);
  };

  /** ความถี่จริง (Hz) ของโน้ตลำดับที่ i ตามระบบเทียบเสียง — ใช้กับโหมดสังเคราะห์ */
  const freqFor = (i) => {
    const m = pack.midi?.[i];
    return m == null ? 0 : noteHz(m, system);
  };

  /** เก็บโหนดไว้ให้ "หยุด" ได้จริง + ปลดออกเองเมื่อเสียงจบ
   *  ★ `when` = เวลาที่จองไว้ว่าจะดัง — ต้องติดไปกับโหนด เพราะตอนเปลี่ยนความเร็ว
   *    กลางเพลงเราต้องแยกให้ออกว่าตัวไหน "ดังไปแล้ว" (ห้ามแตะ) กับตัวไหน
   *    "จองไว้แต่ยังไม่ดัง" (ต้องยกเลิกแล้วจองใหม่ตามความเร็วใหม่) — ดู dropPending */
  const keep = (node, when) => {
    node.__at = when || 0;
    live.push(node);
    node.onended = () => { const k = live.indexOf(node); if (k >= 0) live.splice(k, 1); };
  };

  /** เวลาเริ่มเล่นจริง — 0/ว่าง = "เดี๋ยวนี้" (ต้องแปลงเป็นเวลาสัมบูรณ์ให้ตัวสังเคราะห์) */
  const at0 = (when) => (when && when > 0 ? when : ctx.currentTime + 0.001);

  /** ★ ทางเข้าเดียวของ "เสียงโน้ตหนึ่งตัว" — แซมเปิลหรือสังเคราะห์ก็เรียกตัวนี้ */
  function voice(i, when, gain, durSec) {
    const t = at0(when);
    if (SYNTH) return marimbaStrike(ctx, busInst, freqFor(i), t, gain ?? 0.9, durSec, (n) => keep(n, t));
    const { j, semis } = pickSample(i);
    return strike(bank?.[j], t, gain ?? 0.9, durSec, rateOf(i, semis), busInst);
  }

  // ── บัสเสียงสองเส้น: เครื่องดนตรี / ฉิ่ง–ฉับ ────────────────────────
  //  ★★ ทำไมต้องเป็นบัส ไม่ใช่คูณโวลุ่มตอนจองเสียงทีละตัว ★★
  //   ตัวจองเสียงจองล่วงหน้า **2 วินาที** (LOOKAHEAD) — ถ้าโวลุ่มไปอยู่ที่ค่า gain
  //   ของโน้ตแต่ละตัว เสียงที่จองไปแล้วจะยังดังเท่าเดิมต่ออีก 2 วินาที
  //   ผู้ใช้เลื่อนสไลเดอร์แล้วไม่มีอะไรเกิดขึ้นทันที = อ่านว่า "โปรแกรมค้าง"
  //   → ต่อผ่านบัสแล้วปรับที่บัส เสียงที่จองไปแล้วเปลี่ยนตามทันทีทุกตัว
  //  ★ ปิดเสียง = บัสเป็น 0 · **ไม่หยุดการจองเสียง** เพราะหัวเข็มกับตำแหน่งเพลง
  //    ต้องเดินต่อตามปกติ (ปิดเสียงคือเรื่องของหู ไม่ใช่การหยุดเพลง)
  let busInst = null;
  let busChing = null;
  const level = { inst: 1, ching: 1 };

  /** ทาค่าโวลุ่มลงบัส — ไล่ค่าใน 15 ms กันเสียง "แป๊ะ" ตอนกดปิด/เปิด */
  function paintLevels() {
    if (!ctx) return;
    const now = ctx.currentTime;
    if (busInst) busInst.gain.setTargetAtTime(level.inst, now, 0.015);
    if (busChing) busChing.gain.setTargetAtTime(level.ching, now, 0.015);
  }

  function ensureCtx() {
    if (!ctx) ctx = new (window.AudioContext || window.webkitAudioContext)();
    if (!busInst) {
      busInst = ctx.createGain();
      busChing = ctx.createGain();
      busInst.gain.value = level.inst;
      busChing.gain.value = level.ching;
      busInst.connect(ctx.destination);
      busChing.connect(ctx.destination);
    }
    // ★★ ต้องเป็น "ไม่ใช่ running" ไม่ใช่ "== suspended" ★★
    //   WKWebView ของ macOS พักเสียงด้วยสถานะ 'interrupted' (นอกมาตรฐาน) ตอนจอพัก
    //   เครื่องหลับ หรือแอปอื่นยึดอุปกรณ์เสียงไป · โค้ดเดิมเช็คแค่ 'suspended' จึงไม่ปลุก
    //   แล้วโปรแกรม **เงียบสนิททั้งที่ทุกอย่างดูปกติ** (เจ้าของเจอเอง 2026-08-18:
    //   ทิ้งจอไว้ไปข้างนอก กลับมากดเล่นแล้วไม่มีเสียง)
    // ★ ห้าม await ตรงนี้ — ถ้า engine ไม่ยอมเปิดเสียงจะค้าง · ตัวที่รอคือ wakeCtx
    if (ctx.state !== 'running') ctx.resume().catch(() => {});
    return ctx;
  }

  /**
   * ปลุกระบบเสียงให้ **เดินจริง** ก่อนคำนวณเวลาเริ่มเล่น
   *
   * ★★ ทำไมต้องรอ ไม่ใช่ยิง resume() แล้วไปต่อ ★★ เวลาเริ่มเล่นทุกจุดคิดจาก
   *   `ctx.currentTime` ซึ่ง **ไม่เดิน** ตอน context ยังไม่ตื่น — จองเสียงด้วยเวลานั้น
   *   แล้วพอ context ตื่น นาฬิกาจะกระโดดข้ามไป เสียงที่จองไว้เลยกลายเป็นอดีตทั้งชุด
   *   (เงียบเหมือนเดิม แต่คราวนี้เงียบเพราะจองผิดเวลา ไม่ใช่เพราะยังหลับ)
   * ★ รอไม่เกิน 400 ms แล้วไปต่อไม่ว่าผลจะเป็นยังไง — ระบบเสียงตายก็ต้องกดปุ่มอื่นได้
   * ★★ ปลุกไม่ขึ้น = **ก่อ AudioContext ใหม่ทั้งตัว** เพราะบางครั้ง WebKit คืน context
   *   ที่ resume() ผ่านแต่นาฬิกาไม่เดิน (ตายแล้วแต่ยังรายงานว่าปกติ) · ตอนก่อใหม่ต้อง
   *   ทิ้งแซมเปิลที่ถอดรหัสไว้ด้วย เพราะบัฟเฟอร์ผูกกับ context เดิม → ต้องโหลดใหม่
   * ★ ต้องเรียก **ก่อน** loadBank เสมอ ไม่งั้นล้างของที่เพิ่งโหลดมาทิ้ง
   */
  async function wakeCtx() {
    ensureCtx();
    if (ctx.state === 'running') return true;
    if (await settle(400)) return true;
    // ★★ 'suspended' = ยังไม่ได้รับอนุญาตให้ส่งเสียง (ยังไม่เคยมีคนกดอะไร) — ก่อใหม่
    //   ก็ได้ตัวที่ suspended เหมือนเดิม จึงห้ามก่อ · ตัวที่ต้องก่อใหม่คือ 'interrupted'
    //   (macOS พักเสียงตอนจอพัก) กับ 'closed' (ตายแล้ว) ซึ่ง resume() ปลุกไม่ขึ้นแน่นอน
    if (ctx.state === 'suspended') return false;

    try { await ctx.close(); } catch { /* ปิดไม่ได้ก็ปล่อยให้ GC เก็บ */ }
    ctx = null; busInst = null; busChing = null;
    bank = null; ching = null; loading = null; bankSystem = '';
    ensureCtx();
    return settle(400);
  }

  /**
   * ยิง resume() แล้ว **รอให้สถานะพลิกจริง** ไม่เกิน ms
   * ★★ resume() คืน promise เสร็จ **ก่อน** ที่ state จะกลายเป็น 'running' ได้ ★★
   *   เช็คทันทีหลัง await จะอ่านว่า "ปลุกไม่ขึ้น" ทั้งที่กำลังจะขึ้น — วัดจริงแล้วเจอว่า
   *   ทำให้ก่อ AudioContext ใหม่ทิ้งทุกครั้งโดยไม่จำเป็น (2026-08-18)
   */
  async function settle(ms) {
    ctx.resume().catch(() => {});
    for (let waited = 0; waited < ms; waited += 30) {
      if (ctx.state === 'running') return true;
      await sleep(30);
    }
    return ctx.state === 'running';
  }


  /** ระบบเสียงเดินอยู่จริงไหม — หน้าจอใช้ฟ้องเมื่อกดเล่นแล้วปลุกไม่ขึ้น
   *  (กฎถาวรของโปรเจกต์: "ของที่ผิดแล้วเงียบ ต้องมีอะไรฟ้องเสมอ" — เรื่องนี้เงียบตรงตัว) */
  const audioOk = () => !!ctx && ctx.state === 'running';

  // ★ ปลุกตั้งแต่ตอนคนคลิกกลับเข้าหน้าต่าง ไม่ต้องรอให้กดเล่นก่อน — คนส่วนใหญ่
  //   กดเล่นทันทีที่กลับมา ถ้ารอให้กดก่อนค่อยปลุก ครั้งแรกมักไม่ทัน
  const wakeOnReturn = () => { if (ctx && ctx.state !== 'running') ctx.resume().catch(() => {}); };
  if (typeof window !== 'undefined') {
    window.addEventListener('focus', wakeOnReturn);
    document.addEventListener('visibilitychange', wakeOnReturn);
  }

  async function loadBank() {
    // โหมดสังเคราะห์ไม่มีไฟล์ให้โหลด — เปิด AudioContext พอ
    if (SYNTH) { ensureCtx(); return null; }
    if (bank && (!BANKS_MODE || bankSystem === system)) return bank;
    if (loading) return loading;
    ensureCtx();
    loading = (async () => {
      const jobs = [];
      for (let i = 1; i <= pack.count; i++) {
        jobs.push((async () => {
          for (const ext of EXTS) {
            try {
              const r = await fetch(noteUrl(i, ext));
              if (!r.ok) continue;
              return await ctx.decodeAudioData(await r.arrayBuffer());
            } catch { /* ลองนามสกุลถัดไป */ }
          }
          return null;   // ขาดบางเสียงยังทำงานต่อได้ ดีกว่าเงียบทั้งชุด
        })());
      }
      bank = await Promise.all(jobs);
      bankSystem = system;
      loading = null;
      return bank;
    })();
    return loading;
  }

  /** สลับระบบเทียบเสียง — คืน true ถ้าต้องโหลดไฟล์ใหม่ (โหมด banks) */
  async function setTuning(next) {
    if (!isTuning(next) || next === system) return false;
    stopAll();
    const had = !!bank;
    system = next;
    if (BANKS_MODE) {
      bank = null;
      // ★ โหลดใหม่เฉพาะเมื่อ "เคยโหลดไปแล้ว" — ไม่งั้นแค่คืนค่าที่จำไว้ตอนเปิดแอป
      //   ก็ดึงแซมเปิลทั้งชุด + เปิด AudioContext ทั้งที่ผู้ใช้ยังไม่สั่งให้มีเสียง
      if (had) { await loadBank(); return true; }
    }
    return false;
  }

  async function playIndex(i, enabled = true) {
    if (!enabled || i == null || i < 0) return;
    await wakeCtx();          // ★ ก่อน loadBank เสมอ — ปลุกไม่ขึ้นจะล้างแซมเปิลแล้วโหลดใหม่
    await loadBank();
    voice(i, 0, undefined, null);
  }

  /** ฟังทั้งช่อง — สะบัดไล่กันเหมือนตอนเล่นจริง
   *  ★ จองด้วยเวลาสัมบูรณ์ของ AudioContext (เดิมใช้ setTimeout) — จังหวะสะบัด
   *    ห่างเท่ากันเป๊ะเสมอ ไม่เพี้ยนตามงานอื่นที่หน้าจอกำลังทำอยู่ */
  async function playCell(tokenIndexList, enabled = true) {
    if (!enabled) return;
    await wakeCtx();
    await loadBank();
    const t0 = ctx.currentTime + 0.02;
    (tokenIndexList || []).forEach((i, k) => {
      if (i == null || i < 0) return;
      voice(i, t0 + k * 0.13, undefined, null);
    });
  }

  async function loadChing() {
    if (ching) return ching;
    ensureCtx();
    ching = await Promise.all(['open', 'close'].map(async (n) => {
      for (const ext of ['mp3', 'ogg', 'm4a']) {
        try {
          const r = await fetch(`${CHING_BASE}/${n}.${ext}`);
          if (!r.ok) continue;
          return await ctx.decodeAudioData(await r.arrayBuffer());
        } catch { /* ลองนามสกุลถัดไป */ }
      }
      return null;   // ไม่มีฉิ่งก็ยังฟังทำนองได้
    }));
    return ching;
  }

  /** ตั้งเสียงหนึ่งตัวไว้ที่เวลา when · durSec = ปล่อยนิ้วเมื่อไร (null = ปล่อยจนหมดเอง)
   *  ★ `dest` = บัสที่จะต่อออก (เครื่องดนตรี/ฉิ่ง) — ห้ามต่อตรงเข้าปลายทาง
   *    ไม่งั้นโวลุ่มกับปุ่มปิดเสียงจะคุมเสียงนั้นไม่ได้ */
  function strike(buf, when, gain, durSec, rate, dest) {
    if (!buf) return;
    const s = ctx.createBufferSource();
    s.buffer = buf;
    if (rate && rate !== 1) s.playbackRate.value = rate;
    const g = ctx.createGain();
    g.gain.value = gain;
    s.connect(g).connect(dest || busInst || ctx.destination);
    // ★★ ต้อง start() ก่อนเสมอ แล้วค่อย stop() — สลับลำดับเมื่อไร Web Audio โยน
    //    "cannot call stop without calling start first" แล้วเพลงเงียบสนิททั้งเพลง
    s.start(when);
    if (durSec != null) {
      const rel = Math.max(0.005, (pack.releaseMs || 10) / 1000);
      const off = when + Math.max(0.03, durSec);
      g.gain.setValueAtTime(gain, off);
      g.gain.linearRampToValueAtTime(0.0001, off + rel);
      s.stop(off + rel + 0.01);
    }
    keep(s, when);
  }

  // ── ตัวทยอยจองเสียงล่วงหน้า (look-ahead scheduler) — ห้ามแก้โดยไม่วัดก่อน ──
  const LOOKAHEAD = 2.0;    // วินาที
  const TICK_MS = 250;

  let sched = null;
  let schedTimer = 0;

  /** จองครบแล้วหรือยัง — ทั้งทำนองและฉิ่ง */
  const bookedAll = () => !sched || (sched.ni >= sched.notes.length && sched.ci >= sched.chings.length);

  /** เลิกเติมคิว **แต่ยังจำแผนไว้** — เพลงที่จองครบแล้วยังต้องเปลี่ยนความเร็วได้
   *  (ถ้าทิ้งแผนตรงนี้ ท้ายเพลงจะกลายเป็นช่วงที่ปรับความเร็วไม่ได้เงียบ ๆ) */
  function pausePump() {
    if (schedTimer) { clearInterval(schedTimer); schedTimer = 0; }
  }

  function stopPump() {
    pausePump();
    sched = null;
  }

  function pump() {
    if (!sched) return;
    const { notes, chings, at, vol, sustain, secPerTick } = sched;
    const horizon = ctx.currentTime + LOOKAHEAD;
    while (sched.ni < notes.length && at(notes[sched.ni].t) < horizon) {
      const n = notes[sched.ni++];
      voice(n.i, at(n.t), vol, sustain ? (n.d || 0) * secPerTick : null);
    }
    while (sched.ci < chings.length && at(chings[sched.ci].t) < horizon) {
      const c = chings[sched.ci++];
      // ฉิ่งเป็นแซมเปิลจริงเสมอ แม้ชุดเสียงหลักจะเป็นแบบสังเคราะห์
      // ★ `* 0.5` คือ **สมดุลตั้งต้น** ระหว่างฉิ่งกับทำนอง (ของเดิมตายตัวมาแต่แรก)
      //   โวลุ่มที่ผู้ใช้ปรับไปคูณที่บัส ไม่ใช่ตรงนี้ → ค่าเริ่มต้นจึงดังเท่าเดิมเป๊ะ
      strike(ching?.[c.type] || ching?.[0], at(c.t), vol * 0.5, null, 1, busChing);
    }
    if (sched.ni >= notes.length && sched.ci >= chings.length) pausePump();
  }

  function stopAll() {
    stopPump();
    for (const s of live) { try { s.stop(); } catch { /* หยุดไปแล้ว */ } }
    live = [];
  }

  /**
   * เล่นทั้งเพลงจาก tick ที่กำหนด — คืนจุดอ้างอิงเวลาไว้ให้หน้าจอวิ่งตาม
   * @returns { t0, fromTick, secPerTick, endTick }
   */
  async function playSong(song, secPerTick, opts = {}) {
    await wakeCtx();
    await loadBank();
    await loadChing();
    stopAll();
    const fromTick = Math.max(0, opts.fromTick || 0);
    const vol = opts.volume ?? 0.9;
    // ★ จุดอ้างอิงเวลาอยู่ใน sched (ไม่ใช่ปิดตายในโคลเชอร์) — setTempo ต้องขยับได้
    const at = (t) => sched.t0 + (t - sched.fromTick) * sched.secPerTick;
    // ★ ต้องเรียงตามเวลา เพราะตัวชี้ ni/ci เดินหน้าทางเดียว
    const byT = (a, b) => a.t - b.t;
    sched = {
      notes: (song.notes || []).filter((n) => n.t >= fromTick).sort(byT),
      chings: opts.chingOn === false ? [] : (song.ching || []).filter((c) => c.t >= fromTick).sort(byT),
      at, vol, secPerTick, sustain: !!pack.sustain, ni: 0, ci: 0,
      t0: ctx.currentTime + 0.15, fromTick, endTick: Number(song.lengthTicks) || 0,
    };
    pump();                                     // ชุดแรกต้องพร้อมก่อนคืนค่า
    if (!bookedAll()) schedTimer = setInterval(pump, TICK_MS);   // เพลงสั้นอาจจองครบตั้งแต่รอบแรก
    return anchorOf();
  }

  /** จุดอ้างอิงเวลาที่หน้าจอเอาไปวิ่งหัวเข็มตาม */
  const anchorOf = () => (sched
    ? { t0: sched.t0, fromTick: sched.fromTick, secPerTick: sched.secPerTick, endTick: sched.endTick }
    : null);

  /** ยกเลิกเสียงที่ **จองไว้แต่ยังไม่ดัง** (เสียงที่ออกไปแล้วปล่อยให้จบเอง ไม่งั้นดัง "แป๊ะ") */
  function dropPending(from) {
    for (const n of live.slice()) {
      if (!(n.__at > from)) continue;
      try { n.stop(); } catch { /* หยุดไปแล้ว */ }
      const k = live.indexOf(n);
      if (k >= 0) live.splice(k, 1);
    }
  }

  /** เวลาที่ทิ้งไว้ให้ตัวเองก่อนความเร็วใหม่จะมีผล — ต้องมากพอที่เสียงจะไม่โดนตัดคาปาก
   *  แต่น้อยพอที่ครูจะรู้สึกว่า "กดแล้วเปลี่ยนทันที" */
  const PIVOT_SEC = 0.08;

  /**
   * ★★ เปลี่ยนความเร็วระหว่างเล่นอยู่ ★★ (เจ้าของเจอเอง 2026-08-23:
   *   *"tempo เวลาเลื่อนไม่ทำงานทันที ต้องกดหยุดก่อนแล้วเล่นใหม่"*)
   *
   *  ทำไมของเดิมไม่ขยับ: เวลาของโน้ตทุกตัวคิดจาก secPerTick ที่ส่งมาตอน playSong
   *  ครั้งเดียว — ต่างจากโวลุ่มที่วิ่งผ่านบัสจึงเปลี่ยนได้ทันที (ดูหัวไฟล์ข้อ 4)
   *
   *  วิธี: หา "ห้องที่กำลังจะถึง" (จุดหมุน) ตามความเร็วเดิม → ยกเลิกของที่จองไว้
   *  ข้ามจุดนั้น → ตั้งจุดอ้างอิงเวลาใหม่ → จองใหม่ตามความเร็วใหม่
   *  ★ ไม่แตะเสียงที่ดังไปแล้ว และไม่แตะตำแหน่งบนกระดาษ — เพลงเดินต่อจากที่เดิม
   *
   *  @returns จุดอ้างอิงเวลาชุดใหม่ให้หน้าจอ · null = ไม่ได้เล่นอยู่ (ไม่มีอะไรต้องทำ)
   */
  function setTempo(secPerTick) {
    if (!sched || !ctx || !(secPerTick > 0)) return null;
    if (secPerTick === sched.secPerTick) return anchorOf();
    const pivot = ctx.currentTime + PIVOT_SEC;
    // ★ ยังไม่ทันเริ่มเล่น (t0 อยู่ข้างหน้า) = ยังไม่มีอะไรผ่านไป หมุนที่ห้องเริ่มต้นเลย
    const pivotTick = Math.max(sched.fromTick, sched.fromTick + (pivot - sched.t0) / sched.secPerTick);
    dropPending(pivot);
    // ตัวชี้ต้อง **ถอยกลับ** ไปที่ตัวแรกที่ยังไม่ดัง (ของที่จองข้ามจุดหมุนถูกยกเลิกไปแล้ว)
    const firstFrom = (arr) => { let i = 0; while (i < arr.length && arr[i].t < pivotTick) i++; return i; };
    sched.ni = firstFrom(sched.notes);
    sched.ci = firstFrom(sched.chings);
    sched.t0 = pivot;
    sched.fromTick = pivotTick;
    sched.secPerTick = secPerTick;
    pump();
    if (!schedTimer && !bookedAll()) schedTimer = setInterval(pump, TICK_MS);
    return anchorOf();
  }

  return {
    loadBank,
    setTuning,
    /** ตั้งโวลุ่มของสองบัส (0–1) — ปิดเสียงคือส่ง 0 · มีผลทันทีกับเสียงที่จองไว้แล้ว
     *  ★ ค่าที่ไม่ได้ส่งมาจะไม่ถูกแตะ (ปรับทีละเส้นได้) */
    setLevels(next = {}) {
      if (typeof next.inst === 'number') level.inst = Math.max(0, Math.min(1, next.inst));
      if (typeof next.ching === 'number') level.ching = Math.max(0, Math.min(1, next.ching));
      paintLevels();
    },
    levels: () => ({ ...level }),
    /** ★ เปิดให้ด่านตรวจเรียกได้: โน้ตลำดับที่ i จะใช้ไฟล์เสียงไหน ดัดขึ้น–ลงกี่ครึ่งเสียง
     *  (ดู scripts/probe-transpose.mjs — พิสูจน์เรื่อง "ยืมลูกยอด/ลูกท้าย" โดยไม่ต้องมีหูฟัง) */
    sampleFor: (i) => pickSample(i),
    /** ★ คู่กับ sampleFor — อัตราเร่งที่จะใช้จริงกับลูกที่เลือกมา (ด่านตรวจใช้พิสูจน์
     *  ว่าเสียงที่ยืมมาดัดตกขั้นของระบบเทียบเสียงไทยพอดี ไม่ใช่ครึ่งเสียงสากล) */
    rateFor: (i, semis) => rateOf(i, semis),
    tuning: () => system,
    reloadsOnTuning: () => BANKS_MODE,
    playIndex,
    playCell,
    playSong,
    setTempo,
    stopAll,
    now: () => (ctx ? ctx.currentTime : 0),
    // โหมดสังเคราะห์ไม่มีไฟล์ให้ขาด — คืน 0 เสมอ (null = ยังไม่ได้โหลด)
    missing: () => (SYNTH ? 0 : (bank ? bank.filter((b) => !b).length : null)),
    ready: () => !!bank,
    audioOk,
    /** เก็บกวาดตอนหน้าจอทิ้งชุดเสียงนี้ — ★ ต้องถอดตัวดักเหตุการณ์ด้วย ไม่งั้นชุดเสียง
     *  ถูกสร้างใหม่ทุกครั้งที่เปลี่ยนเครื่องดนตรี แล้วตัวดักค้างสะสมไปเรื่อย ๆ
     *  ★ ปิด context ทิ้งด้วย — WebKit จำกัดจำนวน AudioContext ที่เปิดพร้อมกันได้ */
    dispose() {
      stopAll();
      if (typeof window !== 'undefined') {
        window.removeEventListener('focus', wakeOnReturn);
        document.removeEventListener('visibilitychange', wakeOnReturn);
      }
      if (ctx) { try { ctx.close(); } catch { /* ปิดไม่ได้ก็ปล่อยไป */ } ctx = null; }
      busInst = null; busChing = null; bank = null; ching = null; loading = null;
    },
  };
}
