export const isMac = /Mac|Macintosh|Mac OS X/i.test(navigator.userAgent);

/** ชื่อระบบปฏิบัติการอย่างที่ผู้ใช้เรียกกัน — เอาไปแทรกในข้อความได้เลย */
export const osName = isMac ? 'Mac' : 'Windows';
