// ════════════════════════════════════════════════════════════════════
//  หน้าเปิดใช้งาน — ด่านแรกสุดของโปรแกรม (มาก่อนหน้าแรกด้วย)
//
//  ★ เจ้าของสั่ง 2026-07-30: **ทดลองใช้ 3 วัน** ครบทุกความสามารถ แล้วล็อก
//    → ครั้งแรกที่เปิดโปรแกรมจึงเห็นหน้านี้ พร้อมสองทางเลือกชัด ๆ:
//      "เริ่มทดลองใช้" หรือ "ใส่รหัสที่ซื้อมา"
//    ตั้งใจให้รู้ตั้งแต่วันแรกว่าเป็นของที่ต้องซื้อ ไม่ใช่ไปเจอตอนวันที่ 4
//
//  ★ ต้องมีทางเปิดใช้งานสำหรับเครื่องที่ **ต่อเน็ตไม่ได้** — ห้องซ้อมดนตรีไทย
//    ในโรงเรียนหลายที่ไม่มีเน็ต (ใส่ใบลิขสิทธิ์แบบข้อความ + ที่อยู่หน้าเว็บ)
//
//  ★ ธีมของแอปเป็น **พื้นสว่าง** (--color-cream คือสีตัวหนังสือเข้ม ไม่ใช่พื้น)
//    การ์ดใช้ `glass-card` · ช่องกรอกใช้ `bg-white border-[var(--color-ink-line)]`
//    เหมือนหน้าอื่นทั้งแอป — เคยเขียนผิดเป็นชุดสีพื้นมืดมาแล้วรอบหนึ่ง
//  ★ ห้ามใช้อีโมจิ · เลขสากลทั้งหน้า · ห้ามเอ่ยชื่อเทคโนโลยี (กฎถาวรของโปรเจกต์)
// ════════════════════════════════════════════════════════════════════
import { useState } from 'react';
import { num } from '../lib/num';
import { t } from '../lib/i18n';
import {
  activateError, activateLicense, copyText, installManualLicense, startTrial,
  type LicenseStatus,
} from '../lib/license';

type Props = {
  status: LicenseStatus;
  onChange: (s: LicenseStatus) => void;
};

export default function Activation({ status, onChange }: Props) {
  const [key, setKey] = useState('');
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const [manual, setManual] = useState(false);
  const [manualText, setManualText] = useState('');
  const [copied, setCopied] = useState('');

  const expired = status.state === 'expired';

  const copy = async (what: string, text: string) => {
    if (await copyText(text)) {
      setCopied(what);
      setTimeout(() => setCopied(''), 1500);
    }
  };

  const doActivate = async () => {
    setErr('');
    setBusy(true);
    try {
      const r = await activateLicense(key);
      if (r.ok) onChange(r.status);
      else setErr(activateError(r));
    } catch {
      setErr(t('เปิดใช้งานไม่สำเร็จ กรุณาลองอีกครั้ง'));
    } finally {
      setBusy(false);
    }
  };

  const doManual = async () => {
    setErr('');
    setBusy(true);
    try {
      const r = await installManualLicense(manualText);
      if (r.ok) onChange(r.status);
      else setErr(activateError(r));
    } catch {
      setErr(t('ใส่ใบลิขสิทธิ์ไม่สำเร็จ'));
    } finally {
      setBusy(false);
    }
  };

  const doTrial = async () => {
    setBusy(true);
    try {
      onChange(await startTrial());
    } finally {
      setBusy(false);
    }
  };

  const INPUT = 'w-full h-12 px-4 rounded-xl bg-white border border-[var(--color-ink-line)] text-[15px]';

  return (
    <div className="relative min-h-screen overflow-auto">
      {/* แสงพื้นหลังชุดเดียวกับหน้าแรก — ให้ด่านนี้ดูเป็นส่วนหนึ่งของโปรแกรม
          ไม่ใช่กล่องเตือนที่แปะมาทีหลัง */}
      <div className="pointer-events-none absolute inset-0 overflow-hidden">
        <div className="blob blob-drift" style={{ width: 660, height: 660, left: -220, top: -240, background: 'rgba(224,168,46,.18)' }} />
        <div className="blob blob-drift-slow" style={{ width: 520, height: 520, right: -160, top: 320, background: 'rgba(226,59,46,.07)' }} />
      </div>

      {/* ★★ ผังสองคอลัมน์เมื่อจอกว้าง — จอเจ้าของกว้าง 2560 ถ้าตรึงคอลัมน์เดียว
          แคบ ๆ เนื้อหาจะลอยเป็นเกาะเล็กกลางจอ (ข้อที่เจ้าของเคยตำหนิมาแล้วกับหน้าแรก)
          ★ หน้าต่างเล็กสุดของแอปคือ 1280 — ที่ความกว้างนั้นต้องยุบเป็นคอลัมน์เดียวได้ */}
      <div className="relative z-10 min-h-screen max-w-[1440px] mx-auto px-10 py-12 flex flex-col justify-center">
        <div className="grid gap-10 2xl:gap-16 grid-cols-1 2xl:grid-cols-[minmax(0,1fr)_600px] items-center">
        <header className="flex flex-col gap-4">
          <div className="flex items-center gap-2.5">
            <span className="kicker">ARAN STUDIO</span>
            <span className="h-px flex-1 max-w-[120px] bg-[linear-gradient(90deg,rgba(224,168,46,.6),transparent)]" />
          </div>
          <h1 className="h-display text-[44px] 2xl:text-[62px] leading-[1.05]">THAI SCORE</h1>
          <p className="text-[16px] 2xl:text-[18px] leading-8 2xl:leading-9 text-[var(--color-cream-muted)] max-w-[560px]">
            {expired
              ? t('ช่วงทดลองใช้ {n} วันสิ้นสุดแล้ว — ใส่รหัสที่ซื้อมาเพื่อใช้งานต่อ', { n: num(status.trialDays) })
              : t('โปรแกรมบันทึกโน้ตเพลงไทย — ทดลองใช้ได้ครบทุกความสามารถก่อนตัดสินใจซื้อ')}
          </p>
          {expired && (
            <p className="text-[13.5px] leading-7 text-[var(--color-cream-dim)] max-w-[560px]">
              {t('งานที่เขียนไว้ยังอยู่ครบทุกไฟล์ ไม่ได้หายไปไหน เปิดใช้งานแล้วเขียนต่อได้ทันที')}
            </p>
          )}

          {/* บอกว่าโปรแกรมทำอะไรได้ ก่อนขอให้ตัดสินใจ — คนที่มาถึงหน้านี้ครั้งแรก
              อาจยังไม่เคยเห็นโปรแกรมเลย (ตัวติดตั้งจบแล้วเปิดมาเจอหน้านี้ทันที) */}
          <ul className="flex flex-col gap-2 pt-1 max-w-[560px]">
            {[
              t('เขียนโน้ตไทยบนตารางที่ใช้กันจริง 5 แบบ — ทั่วไป · ฆ้องวง · ร้อง · ขิม · จะเข้'),
              t('กดฟังตรวจทานทันที มีฉิ่ง–ฉับลงจังหวะตามอัตราชั้น'),
              t('เทียบเป็นโน้ตสากลให้เอง ส่งออก MusicXML และ MIDI ได้'),
              t('พิมพ์ลงกระดาษ A4 หรือทำกระดาษตารางเปล่าไปเขียนด้วยมือ'),
            ].map((s) => (
              <li key={s} className="flex items-start gap-2.5 text-[13.5px] 2xl:text-[14.5px] leading-7 text-[var(--color-cream-muted)]">
                <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2.2"
                  className="mt-1.5 shrink-0 text-[var(--color-gold-dark)]">
                  <path d="M4 12.5l5 5L20 6.5" />
                </svg>
                {s}
              </li>
            ))}
          </ul>
        </header>

        <div className="flex flex-col gap-5">

        {/* ── ทดลองใช้ (เห็นเฉพาะตอนยังไม่เคยเริ่ม) ─────────────────── */}
        {status.state === 'none' && (
          <section className="glass-card edge-gold rounded-2xl p-6 flex items-center gap-6">
            <div className="flex-1">
              <div className="text-[17px] font-bold">
                {t('ทดลองใช้ฟรี {n} วัน', { n: num(status.trialDays) })}
              </div>
              <div className="text-[13px] leading-7 text-[var(--color-cream-muted)] mt-1">
                {t('ใช้ได้ครบทุกอย่างเหมือนฉบับเต็ม — เขียนโน้ต · กดฟัง · เทียบโน้ตสากล · พิมพ์ลงกระดาษ · ส่งออกไฟล์ ไม่มีลายน้ำ ไม่จำกัดจำนวนเพลง')}
              </div>
            </div>
            <button className="btn-primary h-12 px-7 rounded-xl text-[15px] whitespace-nowrap"
              disabled={busy} onClick={doTrial}>
              {t('เริ่มทดลองใช้')}
            </button>
          </section>
        )}

        {/* ── ใส่รหัส ─────────────────────────────────────────────────── */}
        <section className="glass-card rounded-2xl p-6 flex flex-col gap-4">
          <div>
            <div className="text-[17px] font-bold">{t('ใส่รหัสที่ซื้อมา')}</div>
            <div className="text-[13px] leading-7 text-[var(--color-cream-muted)] mt-1">
              {t('1 รหัสใช้ได้ 1 เครื่อง · ย้ายไปเครื่องอื่นได้เองภายหลัง')}
            </div>
          </div>

          <div className="flex gap-3">
            <input
              value={key}
              autoFocus
              spellCheck={false}
              placeholder="TSCORE-XXXXX-XXXXX-XXXXX"
              onChange={(e) => setKey(e.target.value.toUpperCase())}
              onKeyDown={(e) => { if (e.key === 'Enter' && key.trim() && !busy) doActivate(); }}
              className={`${INPUT} flex-1 tracking-[.08em] tnum`}
            />
            <button className="btn-primary h-12 px-7 rounded-xl text-[15px] whitespace-nowrap"
              disabled={busy || !key.trim()} onClick={doActivate}>
              {busy ? t('กำลังตรวจสอบ…') : t('เปิดใช้งาน')}
            </button>
          </div>

          {err && (
            <div className="text-[13.5px] leading-7 rounded-xl px-4 py-3"
              style={{
                background: 'rgba(226,59,46,.07)',
                border: '1px solid rgba(226,59,46,.3)',
                color: '#a32a1f',
              }}>
              {err}
            </div>
          )}

          {/* รหัสเครื่อง — ต้องคัดลอกง่าย เพราะเป็นสิ่งที่ลูกค้าต้องส่งให้เราเวลาติดปัญหา */}
          <div className="flex flex-wrap items-center gap-3 pt-3 border-t border-[var(--color-ink-line)]">
            <span className="text-[12.5px] text-[var(--color-cream-dim)]">{t('รหัสเครื่องนี้')}</span>
            <code className="text-[13.5px] tracking-[.08em] tnum">{status.machineCode}</code>
            <button className="text-[12.5px] text-[var(--color-gold-link)] hover:underline"
              onClick={() => copy('machine', status.machineCode)}>
              {copied === 'machine' ? t('คัดลอกแล้ว') : t('คัดลอก')}
            </button>
          </div>
        </section>

        {/* ── ทางสำรองสำหรับเครื่องที่ต่อเน็ตไม่ได้ ────────────────────── */}
        <section className="flex flex-col gap-3">
          <button className="text-[13px] text-[var(--color-cream-muted)] hover:text-[var(--color-cream)] text-left w-fit"
            onClick={() => setManual((v) => !v)}>
            {manual ? '▾' : '▸'} {t('เครื่องนี้ต่ออินเทอร์เน็ตไม่ได้')}
          </button>

          {manual && (
            <div className="glass-card rounded-2xl p-6 flex flex-col gap-3">
              <ol className="text-[13px] leading-8 text-[var(--color-cream-muted)] list-decimal pl-5">
                <li>{t('เปิดหน้าเว็บนี้จากมือถือหรือเครื่องอื่นที่ต่อเน็ตได้')}</li>
                <li className="flex flex-wrap items-center gap-2">
                  <code className="text-[13px] text-[var(--color-cream)]">{status.webActivateUrl}</code>
                  <button className="text-[12.5px] text-[var(--color-gold-link)] hover:underline"
                    onClick={() => copy('url', status.webActivateUrl)}>
                    {copied === 'url' ? t('คัดลอกแล้ว') : t('คัดลอก')}
                  </button>
                </li>
                <li>
                  {t('กรอกรหัสที่ซื้อมา พร้อมรหัสเครื่อง')}{' '}
                  <code className="text-[var(--color-cream)] tnum">{status.machineCode}</code>
                </li>
                <li>{t('คัดลอกข้อความที่ได้มาวางในช่องข้างล่างนี้')}</li>
              </ol>
              <textarea
                value={manualText}
                spellCheck={false}
                rows={5}
                placeholder={t('วางข้อความใบลิขสิทธิ์ทั้งก้อนที่นี่')}
                onChange={(e) => setManualText(e.target.value)}
                className="rounded-xl px-4 py-3 text-[12px] font-mono leading-6 bg-white border border-[var(--color-ink-line)]"
              />
              <button className="btn-glass h-11 px-6 rounded-xl text-[14px] w-fit"
                disabled={busy || !manualText.trim()} onClick={doManual}>
                {t('ใส่ใบลิขสิทธิ์')}
              </button>
            </div>
          )}

          <p className="text-[12.5px] leading-7 text-[var(--color-cream-dim)]">
            {t('ยังไม่มีรหัส? สั่งซื้อได้ที่ thaimusichub.com')}
          </p>
        </section>
        </div>
        </div>
      </div>
    </div>
  );
}
