// ════════════════════════════════════════════════════════════════════
//  วิซาร์ดสร้างเพลงใหม่
//
//  ★★ ต้องเตือนให้ชัดว่า "เลือกแบบโน้ตแล้วเปลี่ยนทีหลังไม่ได้" ★★
//   เจ้าของเคยเลือกผิดบนเว็บโดยไม่รู้ตัว (การ์ดแรกติ๊กไว้เป็นค่าเริ่มต้น) แล้ว
//   ไม่มีอะไรบอกเลยหลังผ่านวิซาร์ด → ที่นี่บอกทั้งในวิซาร์ดและบนแถบหัวจอเขียนโน้ต
//
//  ★ คำอธิบายทุกขั้นเป็นภาษาคน ไม่ใช่ศัพท์เทคนิค — ผู้ใช้คือครูดนตรี ไม่ใช่โปรแกรมเมอร์
// ════════════════════════════════════════════════════════════════════
import { useState } from 'react';
import { blankSong } from '../../packages/engine/score_templates.mjs';
// ★ รายการแบบตารางของ **โปรแกรม** (มีขิม/จะเข้ด้วย) — ดูเหตุผลใน lib/templates.ts
import { WIZARD_TEMPLATES, templateHint, templateName } from '../lib/templates';
import { RATES } from '../../packages/engine/thai_score_edit.mjs';
import { DEFAULT_VIEW, NATAP_SUGGESTIONS, newPage } from '../../packages/engine-ext/thscore_file.mjs';
import { withAccidentals } from '../../packages/engine-ext/accidentals.mjs';
import type { Doc } from '../lib/doc';
import { num } from '../lib/num';
import { t } from '../lib/i18n';

type Props = { onCancel: () => void; onCreate: (doc: Doc) => void };

/** ชื่อขั้นตอน — ต้องตรงกับลำดับ step 0/1/2 ในไฟล์นี้เสมอ */
const steps = () => [t('แบบตาราง'), t('ข้อมูลเพลง'), t('โครงเพลง')];

export default function Wizard({ onCancel, onCreate }: Props) {
  const STEPS = steps();
  const [step, setStep] = useState(0);
  const [inst, setInst] = useState('khong_wong_yai');
  const [title, setTitle] = useState('');
  const [writer, setWriter] = useState('');
  // ★ ช่องรายละเอียดที่ขึ้นหัวกระดาษ — ข้อความล้วนทั้งหมด (ดูคำอธิบายที่ขั้นที่ 2)
  const [rateText, setRateText] = useState('');
  const [natap, setNatap] = useState('');
  const [scribe, setScribe] = useState('');
  const [writtenAt, setWrittenAt] = useState('');
  const [rate, setRate] = useState('สองชั้น');
  const [sections, setSections] = useState(1);
  const [lines, setLines] = useState(2);
  const [bpm, setBpm] = useState(65);

  /** แม่แบบที่เลือกอยู่ — เอาไปโชว์ในแถบสรุปของขั้นที่ 2–3 */
  const chosen = (WIZARD_TEMPLATES as any[]).find((x) => x.id === inst);

  const create = () => {
    // ★ ต่อผังเสียงให้มีครึ่งเสียง ♯/♭ (เฉพาะแบบตารางที่อนุญาต — ดู accidentals.mjs)
    //   ทำตั้งแต่ตอนสร้าง เพราะผังเสียงเป็นข้อมูลในตัวเพลงที่เขียนลงไฟล์
    const song = withAccidentals(blankSong(inst, { title, writer, rate, sections, lines, bpm }));
    // ★ ช่องที่แอปเพิ่มเข้ามา — เขียนทับลงบนเพลงที่เอนจินสร้าง (เอนจินไม่รู้จักช่องพวกนี้
    //   และห้ามแก้เอนจินเพราะ sync มาจากเว็บ · ฟิลด์ optional ฝั่งเว็บ spread ผ่านอยู่แล้ว)
    //   ★ เขียนเฉพาะช่องที่กรอกจริง — ไฟล์ที่ไม่ได้กรอกต้องไม่มีคีย์ว่างค้างไว้
    for (const [k, v] of Object.entries({ rateText, natap, scribe, writtenAt })) {
      if (String(v).trim()) (song as any)[k] = String(v).trim().slice(0, 120);
    }
    // ★ ถอดตัวแปลงชื่อท่อนเลขไทย→เลขสากลออกแล้ว (2026-08-05) — เอนจินตั้งชื่อเป็น
    //   "ท่อน 1" มาตั้งแต่ต้นทางแล้ว ตัวแปลงตรงนี้จึงกลายเป็นโค้ดตาย
    //   ★★ นโยบายเดิมยังอยู่: **เพลงที่เปิดเข้ามาคงชื่อท่อนเดิมของผู้เขียนไว้เสมอ**
    //      ไฟล์เก่าที่เขียนว่า "ท่อน 1" ต้องไม่ถูกแปลงให้ (ชื่อท่อนเป็นข้อมูลของผู้ใช้
    //      ไม่ใช่ข้อความของโปรแกรม)
    onCreate({
      song,
      view: { ...DEFAULT_VIEW } as any,
      page: newPage() as any,
      meta: { createdAt: new Date().toISOString() },
    });
  };

  return (
    <div className="h-full overflow-y-auto overflow-x-hidden relative">
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="blob blob-drift" style={{ width: 600, height: 600, left: -160, top: -200, background: 'rgba(224,168,46,.18)' }} />
        <div className="blob blob-drift-slow" style={{ width: 460, height: 460, right: -150, top: 300, background: 'rgba(226,59,46,.06)' }} />
      </div>
      {/* ★ เหมือนหน้าแรก: หน้าต่างเปิดมาเต็มจอ (2560 บนเครื่องเจ้าของ) ถ้าตรึงแคบ
          เนื้อหาจะลอยเป็นเกาะเล็ก ๆ มีที่ว่างเหลือครึ่งจอ → กว้างขึ้น + จัดกลางแนวตั้ง */}
      <div className="relative z-10 min-h-full max-w-[1120px] 2xl:max-w-[1280px] mx-auto px-10 py-9 flex flex-col justify-center gap-7 2xl:gap-9">
        {/* ★ ตัวบอกขั้นตอนต้องเห็นว่า "อยู่ขั้นไหน เหลืออีกกี่ขั้น และแต่ละขั้นถามอะไร"
            ของเดิมเขียนแค่ "ขั้นที่ 1 จาก 3" ตัวเล็ก ๆ = ไม่รู้ว่าข้างหน้ามีอะไร */}
        <header className="flex flex-col gap-4">
          {/* ★★ ปุ่มเดิน/ออก อยู่ **แถวเดียวกับหัวเรื่อง** ไม่ใช่ท้ายหน้า (ย้าย 2026-08-07
              ตามที่เจ้าของสั่ง) — เนื้อหาแต่ละขั้นสูงไม่เท่ากัน ปุ่มที่อยู่ท้ายหน้าจึง
              **ขยับขึ้นลงทุกครั้งที่เปลี่ยนขั้น** ต้องเล็งใหม่ทุกที · อยู่บนแล้วนิ่ง
              ที่เดิมเสมอ และอยู่ใกล้แถบขั้นตอนซึ่งเป็นเรื่องเดียวกัน (เดินหน้า-ถอยหลัง)
              ★ ปุ่มหลักชิดขวาสุดตรงกับขอบเนื้อหาพอดี ปุ่มรองอยู่ติดกันทางซ้ายของมัน
                — สายตาไล่ซ้าย→ขวาแล้วจบที่ปุ่มที่ต้องกดต่อ */}
          <div className="flex items-center gap-4 flex-wrap">
            <h1 className="h-display text-[32px] 2xl:text-[40px] mr-auto">{t('เขียนโน้ตใหม่')}</h1>
            <button className="btn-glass h-11 px-5 rounded-xl flex-none" onClick={step === 0 ? onCancel : () => setStep(step - 1)}>
              {step === 0 ? t('ยกเลิก') : `← ${t('ย้อนกลับ')}`}
            </button>
            {step < 2 ? (
              <button className="btn-primary h-11 px-6 rounded-xl flex-none" onClick={() => setStep(step + 1)}>{t('ต่อไป')} →</button>
            ) : (
              <button className="btn-primary h-11 px-6 rounded-xl flex-none" onClick={create}>{t('สร้างกระดาษโน้ต')}</button>
            )}
          </div>
          <div className="flex items-center gap-0">
            {STEPS.map((s, i) => (
              <div key={s} className="flex items-center" style={{ flex: i < STEPS.length - 1 ? 1 : 'none' }}>
                <div className="flex items-center gap-2.5 flex-none">
                  <span
                    className="w-8 h-8 grid place-items-center rounded-full text-[13.5px] font-bold tnum flex-none"
                    style={
                      i < step
                        ? { background: 'rgba(43,122,85,.14)', color: '#26694a', border: '1px solid rgba(43,122,85,.4)' }
                        : i === step
                          ? { background: 'linear-gradient(135deg,#f7d778,#e0a82e 55%,#c98a16)', color: '#3a2a08', boxShadow: '0 6px 16px -8px rgba(224,168,46,.9)' }
                          : { background: '#fff', color: 'var(--color-cream-dim)', border: '1px solid var(--color-ink-line)' }
                    }
                  >
                    {i < step ? '✓' : num(i + 1)}
                  </span>
                  <span
                    className="text-[13px] whitespace-nowrap"
                    style={{
                      fontWeight: i === step ? 700 : 400,
                      color: i === step ? 'var(--color-cream)' : 'var(--color-cream-dim)',
                    }}
                  >
                    {s}
                  </span>
                </div>
                {i < STEPS.length - 1 && (
                  <span className="h-px flex-1 mx-3"
                    style={{ background: i < step ? 'rgba(43,122,85,.45)' : 'var(--color-ink-line)' }} />
                )}
              </div>
            ))}
          </div>
        </header>

        {step === 0 && (
          <section className="flex flex-col gap-4">
            <h2 className="h-display text-[19px]">{t('จะเขียนโน้ตแบบไหน')}</h2>
            {/* ★★ รายการมาจาก lib/templates.ts ของ **โปรแกรม** ไม่ใช่จากเอนจินตรง ๆ
                เอนจิน (sync มาจากเว็บ) ให้แค่ 3 แบบ · ขิม/จะเข้เป็นของคนซื้อโปรแกรม
                เจ้าของยืนยัน 2026-08-05 ว่า **ไม่ได้ตัดทิ้ง** ยังสร้างงานใหม่ได้ที่นี่ */}
            <div className="grid grid-cols-2 gap-4 2xl:gap-6">
              {WIZARD_TEMPLATES.map((tpl: any) => {
                const on = inst === tpl.id;
                const names = (tpl.staveNames || []).filter(Boolean);
                return (
                  <button
                    key={tpl.id}
                    className="glass-card edge-gold lift rounded-2xl p-5 text-left flex flex-col gap-2.5 relative"
                    style={{
                      outline: on ? '2px solid var(--color-gold)' : 'none',
                      outlineOffset: 2,
                      background: on ? 'rgba(255,253,246,.82)' : undefined,
                    }}
                    onClick={() => setInst(tpl.id)}
                  >
                    {/* ★ ป้ายติ๊กมุมขวา — ของเดิมบอกว่าเลือกอันไหนด้วยเส้นขอบทองบาง ๆ
                        อย่างเดียว มองข้ามได้ง่ายมาก และวิซาร์ดนี้เป็นจุดที่ "เลือกผิด
                        แล้วต้องเริ่มเพลงใหม่" จึงต้องเห็นชัดที่สุด */}
                    {on && (
                      <span className="absolute top-3 right-3 w-6 h-6 grid place-items-center rounded-full text-[13px] font-bold"
                        style={{ background: 'linear-gradient(135deg,#f7d778,#e0a82e 55%,#c98a16)', color: '#3a2a08' }}>
                        ✓
                      </span>
                    )}
                    <StaveIcon lines={tpl.hands || 1} />
                    <span className="h-display text-[18px]">
                      {templateName(tpl)}
                      <span className="ml-2 text-[13px] font-normal text-[var(--color-cream-muted)]">
                        {t('{n} บรรทัด', { n: num(tpl.hands || 1) })}
                      </span>
                    </span>
                    {names.length > 0 && (
                      <span className="flex flex-wrap gap-1.5">
                        {names.map((n: string) => (
                          <span key={n} className="text-[11.5px] px-2 py-0.5 rounded-full"
                            style={{ background: 'rgba(224,168,46,.15)', color: 'var(--color-gold-deep)' }}>
                            {n}
                          </span>
                        ))}
                      </span>
                    )}
                    {/* ★ คำอธิบายมาจาก packages/engine/ ที่ห้ามแก้ — templateHint()
                        แปลงเลขไทยให้ และสลับเป็นคำอธิบายอังกฤษเมื่อเปลี่ยนภาษา */}
                    <span className="text-[12.5px] leading-6 text-[var(--color-cream-muted)]">{templateHint(tpl)}</span>
                  </button>
                );
              })}
            </div>
            <p
              className="text-[13px] px-4 py-3 rounded-xl"
              style={{ background: 'rgba(226,59,46,.07)', border: '1px solid rgba(226,59,46,.28)' }}
            >
              <b className="text-[var(--color-siam)]">{t('เลือกให้ดีก่อนไปต่อ')}</b>
              {' — '}
              {t('จำนวนบรรทัดของเพลงนี้เปลี่ยนทีหลังไม่ได้ ถ้าเลือกผิดต้องเริ่มเพลงใหม่')}
            </p>
          </section>
        )}

        {/* ★ ขั้นที่ 2–3 ต้องเห็นว่า "แบบตารางที่เลือกไว้คืออะไร" ตลอดเวลา — มันเปลี่ยน
            ทีหลังไม่ได้ ถ้าจำผิดแล้วกดสร้างไปเลยคือต้องเริ่มเพลงใหม่ทั้งเพลง */}
        {step > 0 && (
          <div className="flex items-center gap-2.5 px-4 py-2.5 rounded-xl text-[13px]"
            style={{ background: 'rgba(224,168,46,.1)', border: '1px solid rgba(224,168,46,.32)' }}>
            <StaveIcon lines={chosen?.hands || 1} />
            <span className="text-[var(--color-cream-muted)]">{t('แบบตารางที่เลือก')}</span>
            <b className="text-[var(--color-gold-deep)]">
              {templateName(chosen)} · {t('{n} บรรทัด', { n: num(chosen?.hands || 1) })}
            </b>
            <div className="flex-1" />
            <button className="text-[12.5px] underline text-[var(--color-cream-muted)] hover:text-[var(--color-cream)]"
              onClick={() => setStep(0)}>
              {t('กลับไปเปลี่ยน')}
            </button>
          </div>
        )}

        {step === 1 && (
          <section className="flex flex-col gap-4">
            <h2 className="h-display text-[19px]">{t('ข้อมูลเพลง')}</h2>
            {/* ★★ ช่องทั้งหมดที่ขึ้นหัวกระดาษอยู่ที่นี่ตั้งแต่ตอนสร้างเพลงเลย ★★
                (เจ้าของสั่งย้ายมา 2026-08-07) — ของเดิมกรอกได้แค่ชื่อเพลงกับผู้เขียน
                ที่เหลือต้องไปหาในกล่องรายละเอียดเพลงทีหลัง คนสร้างเพลงใหม่จึงไม่รู้
                ว่ากรอกอะไรได้บ้าง · เว้นว่างได้ทุกช่อง แก้ทีหลังได้ที่กล่องเดียวกัน
                ★ **ทุกช่องเป็นข้อความล้วน** ห้ามผูกกับค่าที่ระบบคำนวณ (จังหวะของ
                  เพลงหนึ่งเพลงมีได้หลายอัตรา + มีจังหวะพิเศษที่ระบบไม่รู้จัก) */}
            <p className="text-[12.5px] text-[var(--color-cream-muted)] -mt-1">
              {t('ทุกช่องเว้นว่างได้ · ช่องที่กรอกจะขึ้นบนหัวกระดาษตอนพิมพ์ (เลือกซ่อนทีหลังได้)')}
            </p>
            <Row label={t('ชื่อเพลง')} hint={t('ขึ้นหัวกระดาษตอนพิมพ์')}>
              <input className="w-full h-11 px-3 rounded-xl bg-white border border-[var(--color-ink-line)]"
                value={title} onChange={(e) => setTitle(e.target.value)} placeholder={t('เช่น ลาวดวงดอกไม้')} />
            </Row>
            <div className="grid grid-cols-2 gap-4">
              <Row label={t('จังหวะ')} hint={t('พิมพ์ได้ตามจริง เช่น สองชั้น · สามชั้น–สองชั้น–ชั้นเดียว')}>
                <input className="w-full h-11 px-3 rounded-xl bg-white border border-[var(--color-ink-line)]"
                  value={rateText} onChange={(e) => setRateText(e.target.value)} />
              </Row>
              <Row label={t('หน้าทับ')} hint={t('เลือกจากรายการ หรือพิมพ์ชื่ออื่นเองได้')}>
                <input className="w-full h-11 px-3 rounded-xl bg-white border border-[var(--color-ink-line)]"
                  list="wz-natap" value={natap} onChange={(e) => setNatap(e.target.value)} />
                <datalist id="wz-natap">
                  {NATAP_SUGGESTIONS.map((v: string) => <option key={v} value={v} />)}
                </datalist>
              </Row>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <Row label={t('ผู้ประพันธ์เพลง')}>
                <input className="w-full h-11 px-3 rounded-xl bg-white border border-[var(--color-ink-line)]"
                  value={writer} onChange={(e) => setWriter(e.target.value)} />
              </Row>
              <Row label={t('ผู้บันทึกโน้ต')}>
                <input className="w-full h-11 px-3 rounded-xl bg-white border border-[var(--color-ink-line)]"
                  value={scribe} onChange={(e) => setScribe(e.target.value)} />
              </Row>
            </div>
            <Row label={t('วันที่บันทึก')} hint={t('พิมพ์เองได้ตามที่อยากให้ขึ้นกระดาษ')}>
              <div className="flex gap-2">
                <input className="flex-1 h-11 px-3 rounded-xl bg-white border border-[var(--color-ink-line)]"
                  value={writtenAt} onChange={(e) => setWrittenAt(e.target.value)} />
                {/* ★ ปุ่มช่วยพิมพ์เฉย ๆ — ค่าที่ได้เป็นข้อความที่แก้ต่อได้ ไม่ใช่วันที่
                    ของระบบที่เปลี่ยนเองตอนบันทึก (เจ้าของเลือก "กรอกเอง") */}
                <button className="btn-glass h-11 px-4 rounded-xl text-[13px] flex-none"
                  onClick={() => setWrittenAt(new Date().toLocaleDateString('th-TH', { day: 'numeric', month: 'long', year: 'numeric' }))}>
                  {t('วันนี้')}
                </button>
              </div>
            </Row>
          </section>
        )}

        {step === 2 && (
          <section className="flex flex-col gap-4">
            <h2 className="h-display text-[19px]">{t('โครงเพลง')}</h2>
            <Row label={t('อัตราจังหวะ')} hint={t('กำหนดว่าฉิ่ง-ฉับ ตีถี่แค่ไหน · เปลี่ยนรายท่อนได้ทีหลัง')}>
              <div className="flex gap-2">
                {RATES.map((r: string) => (
                  <button key={r}
                    className="h-10 px-4 rounded-xl text-[13.5px]"
                    style={{
                      background: rate === r ? 'linear-gradient(135deg,#f7d778,#e0a82e 55%,#c98a16)' : '#fff',
                      border: rate === r ? 'none' : '1px solid var(--color-ink-line)',
                      fontWeight: rate === r ? 600 : 400,
                      color: rate === r ? '#3a2a08' : 'var(--color-cream)',
                    }}
                    onClick={() => setRate(r)}>{r}</button>
                ))}
              </div>
              <p className="text-[12px] text-[var(--color-cream-dim)] mt-1">
                {t('สามชั้น = ฉิ่ง 1 ครั้งทุก 2 ห้อง · สองชั้น = 1 ครั้ง/ห้อง · ชั้นเดียว = 2 ครั้ง/ห้อง')}
              </p>
            </Row>
            <div className="grid grid-cols-3 gap-4">
              <Row label={t('จำนวนท่อน')}><Num v={sections} set={setSections} min={1} max={12} /></Row>
              <Row label={t('บรรทัดต่อท่อน')} hint={t('1 บรรทัด = 8 ห้อง')}><Num v={lines} set={setLines} min={1} max={16} /></Row>
              <Row label={t('ความเร็ว (BPM)')}><Num v={bpm} set={setBpm} min={30} max={140} step={5} /></Row>
            </div>
            <p className="text-[12.5px] text-[var(--color-cream-muted)]">
              {t('เพิ่มบรรทัด/ท่อนทีหลังได้ตลอด — ตรงนี้แค่ตั้งต้นให้พอเขียน')}
            </p>
          </section>
        )}

        {/* ★ ไม่มีแถบปุ่มท้ายหน้าแล้ว — **ห้ามเอากลับมา** ปุ่มชุดเดียวกันสองที่
            ทำให้ผู้ใช้ต้องมองสองจุดว่าอันไหนใช้ได้ (ดูเหตุผลเต็มที่ header) */}
      </div>
    </div>
  );
}

// ★ ช่องกรอกต้อง "ยึดขอบล่าง" เสมอ — ไม่งั้นช่องที่มีคำอธิบายใต้ป้ายจะถูกดันต่ำ
//   กว่าเพื่อนในแถวเดียวกัน (เจ้าของเห็นแล้วทัก 2026-07-29: ช่อง "บรรทัดต่อท่อน"
//   ต่ำกว่า "จำนวนท่อน" กับ "ความเร็ว" เพราะมันมีบรรทัด hint เพิ่มมาหนึ่งบรรทัด)
function Row({ label, hint, children }: { label: string; hint?: string; children: React.ReactNode }) {
  return (
    <label className="flex flex-col gap-1.5 h-full">
      <span className="text-[13.5px] font-semibold">{label}</span>
      {hint && <span className="text-[12px] text-[var(--color-cream-dim)] -mt-1">{hint}</span>}
      <div className="mt-auto">{children}</div>
    </label>
  );
}

/** รูปตารางย่อของแบบนั้น ๆ — เห็นว่า "3 บรรทัด" หน้าตาเป็นอย่างไรก่อนเลือก
 *  ★ ของเดิมใช้ตัวอักษร ▤ ซ้ำ ๆ ตามจำนวนบรรทัด ซึ่งอ่านไม่ออกว่าคืออะไร
 *  ★ วาดด้วย SVG ไม่ใช่อีโมจิ/อักขระพิเศษ — คุมหน้าตาได้เท่ากันทุกเครื่อง */
function StaveIcon({ lines }: { lines: number }) {
  const H = 11;          // ความสูงของหนึ่งบรรทัด
  const G = 4;           // ช่องไฟระหว่างบรรทัด
  const W = 96;
  const total = lines * H + (lines - 1) * G;
  return (
    <svg width={W} height={total} viewBox={`0 0 ${W} ${total}`} fill="none" aria-hidden>
      {Array.from({ length: lines }, (_, i) => {
        const y = i * (H + G);
        return (
          <g key={i}>
            <rect x="0.5" y={y + 0.5} width={W - 1} height={H - 1} rx="1.5"
              stroke="var(--grid-line)" fill="#fff" />
            {/* เส้นแบ่ง 4 ช่องในหนึ่งห้อง + พื้นอ่อนที่ช่องจังหวะตก (ช่องท้าย) */}
            <rect x={W - 24} y={y + 1} width="23" height={H - 2} fill="rgba(224,168,46,.16)" />
            {[1, 2, 3].map((k) => (
              <line key={k} x1={(W / 4) * k} y1={y + 1} x2={(W / 4) * k} y2={y + H - 1}
                stroke="var(--grid-line)" strokeWidth="0.75" />
            ))}
          </g>
        );
      })}
    </svg>
  );
}

function Num({ v, set, min, max, step = 1 }: { v: number; set: (n: number) => void; min: number; max: number; step?: number }) {
  return (
    <div className="flex items-center h-11 rounded-xl bg-white border border-[var(--color-ink-line)] overflow-hidden">
      <button className="w-11 h-full text-[17px] text-[var(--color-cream-muted)] hover:bg-[rgba(224,168,46,.14)]"
        onClick={() => set(Math.max(min, v - step))}>−</button>
      <div className="flex-1 text-center text-[15px] font-semibold tnum">{num(v)}</div>
      <button className="w-11 h-full text-[17px] text-[var(--color-cream-muted)] hover:bg-[rgba(224,168,46,.14)]"
        onClick={() => set(Math.min(max, v + step))}>＋</button>
    </div>
  );
}
