// ════════════════════════════════════════════════════════════════════
//  ลิขสิทธิ์ + ช่วงทดลองใช้ — ฝั่งหน้าจอ
//
//  ★ หน้าจอ **ไม่ต่ออินเทอร์เน็ตเอง** ทุกอย่างวิ่งผ่านฝั่งเนทีฟ (license.rs)
//    ดูเหตุผลใน src-tauri/src/license_net.rs
//  ★ ที่นี่คือที่เดียวที่แปล "รหัสเหตุผล" เป็นข้อความไทย — ฝั่งเนทีฟกับเว็บส่ง
//    มาแค่รหัส เพื่อให้เปลี่ยนคำพูดได้โดยไม่ต้องแก้สองฝั่ง
//  ★ รหัสที่ไม่รู้จัก **ต้องไม่ทำให้จอว่าง** — เว็บอาจเพิ่มรหัสใหม่ในอนาคต
//    แล้วโปรแกรมรุ่นนี้ยังอยู่ในเครื่องลูกค้า (จึงมีข้อความกลางไว้รับ)
// ════════════════════════════════════════════════════════════════════
import { invoke } from '@tauri-apps/api/core';
import { num } from './num';
import { t } from './i18n';

export type LicenseState = 'licensed' | 'trial' | 'expired' | 'none' | 'unconfigured';

export type LicenseStatus = {
  state: LicenseState;
  machineCode: string;
  name: string;
  key: string;
  daysLeft: number;
  trialDays: number;
  /** จริง = ใช้โปรแกรมได้ทุกอย่าง · เท็จ = ต้องเปิดใช้งานก่อน */
  allowed: boolean;
  webActivateUrl: string;
};

export type ActivateOutcome = {
  ok: boolean;
  error: string;
  message: string;
  retryAfterDays: number;
  status: LicenseStatus;
};

export const licenseStatus = () => invoke<LicenseStatus>('license_status');
export const startTrial = () => invoke<LicenseStatus>('license_start_trial');
export const activateLicense = (key: string) => invoke<ActivateOutcome>('license_activate', { key });
export const installManualLicense = (text: string) => invoke<ActivateOutcome>('license_install_manual', { text });
export const deactivateLicense = () => invoke<ActivateOutcome>('license_deactivate');

/** ข้อความไทยของผลที่ไม่สำเร็จ */
export function activateError(o: ActivateOutcome): string {
  // ความผิดพลาดฝั่งเครื่องนี้มีข้อความมาพร้อมแล้ว (ต่อเน็ตไม่ได้ · เขียนไฟล์ไม่ได้ ฯลฯ)
  if (o.message) return o.message;
  switch (o.error) {
    case 'invalid_key':
      return t('ไม่พบรหัสนี้ในระบบ — ตรวจตัวอักษรอีกครั้ง (พิมพ์ใหญ่-เล็กไม่สำคัญ)');
    case 'revoked':
      return t('รหัสนี้ถูกยกเลิกแล้ว กรุณาติดต่อผู้จำหน่าย');
    case 'machine_limit':
      return o.retryAfterDays > 0
        ? t('รหัสนี้ถูกใช้กับเครื่องอื่นอยู่ — เปิดโปรแกรมในเครื่องเดิมแล้วกด "ย้ายเครื่องนี้ออก" ก่อน')
          + ' ' + t('(ถ้าเครื่องเดิมเสียจนเปิดไม่ได้ ระบบจะปล่อยให้เองในอีก {n} วัน)', { n: num(o.retryAfterDays) })
        : t('รหัสนี้ถูกใช้กับเครื่องอื่นอยู่ — ย้ายเครื่องเดิมออกก่อน');
    case 'rehost_limit':
      return t('ย้ายเครื่องเกินจำนวนที่กำหนดในรอบปีนี้ กรุณาติดต่อผู้จำหน่าย');
    case 'bad_request':
      return t('รูปแบบรหัสไม่ถูกต้อง — ต้องเป็น TSCORE ตามด้วยตัวอักษร 3 กลุ่ม');
    case 'no_license':
      return t('เครื่องนี้ยังไม่ได้เปิดใช้งาน');
    default:
      return t('เปิดใช้งานไม่สำเร็จ กรุณาลองอีกครั้ง หรือติดต่อผู้จำหน่าย');
  }
}

/** คัดลอกข้อความ — เผื่อทางที่สองไว้ เพราะช่องทางปกติถูกปิดได้ในหน้าต่างแบบนี้ */
export async function copyText(s: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(s);
    return true;
  } catch {
    try {
      const ta = document.createElement('textarea');
      ta.value = s;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      const ok = document.execCommand('copy');
      document.body.removeChild(ta);
      return ok;
    } catch {
      return false;
    }
  }
}
