import { t } from './i18n';

/** ════════════════════════════════════════════════════════════════════
 *  ชื่อเพลงที่แสดงบนจอ / บนหัวกระดาษ
 *
 *  ★★ ทำไมต้องมีฟังก์ชันนี้ (เจอตอนไล่จอจริงเป็นภาษาอังกฤษ 2026-08-06) ★★
 *   `blankSong()` ในเอนจินตั้งชื่อตั้งต้นให้เป็น **"โน้ตไม่มีชื่อ"** เมื่อผู้ใช้
 *   ไม่กรอกชื่อเพลง (score_templates.mjs) — ไม่ใช่ชื่อที่ผู้ใช้ตั้ง แต่เป็น
 *   **ข้อความของโปรแกรม** ที่หลุดไปอยู่ในข้อมูลเพลง
 *   ผลคือเปิดภาษาอังกฤษแล้วแถบหัวยังขึ้นภาษาไทยอยู่คำเดียว โดยที่ตัว
 *   `song.title || t('ยังไม่ตั้งชื่อ')` ไม่มีวันทำงาน เพราะ title ไม่เคยว่าง
 *   ★ แก้ฝั่งเอนจินไม่ได้ (sync มาจากเว็บ · verify:sync ฟ้อง sha256 ทันที)
 *     จึงดักที่ **ตอนแสดงผล** แทน — ข้อมูลในไฟล์ไม่ขยับสักไบต์ ไฟล์ที่ลูกค้า
 *     บันทึกไว้แล้วยังเปิดในเว็บได้เหมือนเดิม
 * ════════════════════════════════════════════════════════════════════ */
const ENGINE_UNTITLED = 'โน้ตไม่มีชื่อ';

export function songTitle(song: any): string {
  const s = String(song?.title ?? '').trim();
  if (!s || s === ENGINE_UNTITLED) return t('ยังไม่ตั้งชื่อ');
  return s;
}

export type View = {
  barPhase: 'end' | 'downbeat';
  layout: 'thai' | 'split' | 'western';
  tuning: string;
  chingOn: boolean;
  /** ซ้ำท่อนตามจำนวนเที่ยวที่เขียนไว้ที่หัวท่อน (ปิด = ท่อนละเที่ยวเดียว) */
  repeatOn: boolean;
  zoom: number;
  splitRatio: number;
};

export type Page = {
  size: 'A4';
  orientation: 'portrait' | 'landscape';
  marginMm: number;
  fontScale: number;
  lineGap: number;
  what: 'both' | 'thai' | 'western';
  /** ความสูงบรรทัดโน้ตสากลเป็นมิลลิเมตรบนกระดาษจริง (rastral)
   *  (ดู DEFAULT_PAGE + staffHeightMm ใน packages/engine-ext/thscore_file.mjs)
   *  ★ optional เพราะไฟล์ที่บันทึกไว้ก่อน 2026-08-07 ไม่มีฟิลด์นี้ */
  wnStaffMm?: number;
  /** ห้องต่อบรรทัดของโน้ตสากล — ตัวคุม "ความโปร่ง" (โน้ตสากลตีพิมพ์จริงใช้ 4)
   *  ★ อิสระจาก wnStaffMm: fitWestern หา beatW ที่ให้ได้ทั้งสองค่าพร้อมกัน
   *  ★ ไฟล์ก่อน 2026-08-07 มี `wnBeatW` แทน — ตกมาที่ค่าปริยาย ไม่ต้องแปลง
   *    (beatW เป็นหน่วยภายในของเอนจิน ไม่ใช่สิ่งที่ผู้ใช้ตั้งอีกต่อไป) */
  wnBarsPerLine?: number;
  /** รวบสองมือเป็นบรรทัดเดียวแบบคอร์ดบนแผ่นสากล (ครูขอมา 2026-08-16) */
  wnMerge?: boolean;
  /** อะไรบ้างที่ให้ขึ้นบนหัวกระดาษ — ดู HEAD_FIELDS ใน thscore_file.mjs
   *  ★ optional ทั้งก้อน · ไฟล์เก่าที่ไม่มีฟิลด์นี้ตกมาที่ค่าปริยาย */
  head?: Partial<Record<HeadField, boolean>>;
};

/** ★★ ช่องรายละเอียดเพลงที่ขึ้นหัวกระดาษได้ — **ทุกช่องเป็นข้อความล้วน** ★★
 *  เจ้าของสั่ง 2026-08-07: *"เป็นข้อความบอกรายละเอียดเพลง ไม่ใช่ฟังก์ชัน"*
 *  → ห้ามผูกกับค่าที่ระบบคำนวณเอง (เช่นดึงอัตราจังหวะจาก `sections[].rate`
 *    หรือ BPM) เพราะเพลงเดียวมีหลายอัตราจังหวะได้ และยังมีจังหวะพิเศษที่
 *    ระบบไม่รู้จัก · คนเขียนโน้ตต้องพิมพ์สิ่งที่ถูกต้องเองได้เสมอ */
export type HeadField =
  | 'title'       // ชื่อเพลง        → song.title
  | 'rateText'    // จังหวะ          → song.rateText
  | 'natap'       // หน้าทับ         → song.natap
  | 'instrument'  // เครื่องดนตรี     → song.instrumentTh
  | 'writer'      // ผู้ประพันธ์เพลง  → song.writer
  | 'scribe'      // ผู้บันทึกโน้ต    → song.scribe
  | 'writtenAt';  // วันที่บันทึก     → song.writtenAt (ข้อความ ไม่ใช่วันที่ของระบบ)

export type Doc = {
  song: any;
  view: View;
  page: Page;
  meta: Record<string, any>;
};

/** งานที่เปิดอยู่ + ที่อยู่ไฟล์บนดิสก์ (null = ยังไม่เคยบันทึก) */
export type OpenFile = {
  doc: Doc;
  path: string | null;
  dirty: boolean;
};
