//  ระบบเทียบเสียงไทย — ตารางความถี่ + สูตรแปลงเป็นอัตราเร่งเสียง
//
//  สกัดออกมาจาก ScorePlayer.astro (2026-07-27) ตอนทำให้หน้าแก้โน้ตของแอดมิน
//  เลือกเทียบเสียงได้เหมือนหน้าเพลงจริง — ★ ต้องมีสำเนาเดียวในเว็บทั้งเว็บ
//  ถ้าปล่อยให้ก๊อปไปไว้สองที่ วันหนึ่งจะแก้ที่เดียวแล้วสองหน้าให้เสียงคนละอย่าง
//  โดยไม่มีอะไรฟ้อง (คนแก้โน้ตจะจูนตามเสียงที่ผิดจากที่คนฟังได้ยิน)
//
//  ตารางความถี่ยกมาจาก KHIM/khim/lib/core/constants/thai_frequencies.dart
//  (แหล่งเดียวกับที่แอปขิมใช้ — อย่าปัดเศษหรือคำนวณเองใหม่ ใช้ตัวเลขในตารางตรง ๆ)
// ════════════════════════════════════════════════════════════════════

/** รายการระบบเทียบเสียงสำหรับทำปุ่มเลือก — เรียงตามที่โชว์บนหน้าเพลงจริง */
export const TUNING_SYSTEMS = [
  { id: 'chromatic', label: 'สากล', title: 'เทียบเสียงสากล (A4 = 440 Hz)' },
  { id: 'royal', label: 'พระราชทาน', title: 'ระบบหลวงประดิษฐไพเราะ — อ้างเสียงโอด ลา = 828 Hz' },
  { id: 'silpa', label: 'กรมศิลป์', title: 'ระบบกรมศิลปากร — ต่ำกว่าสากลราวสองเสียง' },
];

export const TUNING_IDS = TUNING_SYSTEMS.map((s) => s.id);
export const isTuning = (s) => TUNING_IDS.includes(s);

//  พระราชทาน — อ้างเสียงโอด ลา = 828 Hz (จุฬาลงกรณ์มหาวิทยาลัย)
const ROYAL = {
  3: [252, 279, 308, 340, 375, 414, 457],
  4: [505, 557, 615, 679, 750, 828, 914],
  5: [1009, 1114, 1230, 1358, 1500, 1656, 1828],
  6: [2019, 2229, 2461, 2717, 3000, 3312, 3657],
};
//  กรมศิลปากร — ต่ำกว่าสากลราวสองเสียงตามตารางจริง
const SILPA = {
  0: [115.2, 127.1, 140.4, 155.0, 171.1, 188.9, 208.6],
  1: [230.3, 254.2, 280.7, 309.9, 342.2, 377.8, 417.2],
  2: [460.6, 508.4, 561.4, 619.8, 684.4, 755.6, 834.4],
  3: [921.2, 1016.8, 1122.8, 1239.6, 1368.8, 1511.2, 1668.8],
  4: [1842.4, 2033.6, 2245.6, 2479.2, 2737.6, 3022.4, 3337.6],
};
// โน้ตไทย 7 เสียงจับกับคีย์ขาว: C=ด D=ร E=ม F=ฟ G=ซ A=ล B=ท (คีย์ดำไม่มีในโน้ตไทย)
const WHITE = { 0: 0, 2: 1, 4: 2, 5: 3, 7: 4, 9: 5, 11: 6 };

/** อัตราส่วนความเร็วเล่นที่ทำให้โน้ต MIDI นี้ไปตรงความถี่ของระบบที่เลือก
 *  1.0 = ไม่ปรับ (สากล · คีย์ดำ · หรือโน้ตที่อยู่นอกช่วงตาราง)
 *
 *  ★ ใช้เฉพาะชุดเสียงโหมด 'ratio' คือชุดที่อัดตามเทียบเสียงสากลชุดเดียว
 *    (ขลุ่ยจาก KHITA · และเครื่องดนตรีตัวใหม่ ๆ ต่อจากนี้)
 *    ฆ้องวงเป็นโหมด 'banks' มีชุดอัดจริงครบสามระบบอยู่แล้ว **ห้ามเอาสูตรนี้ไปคูณซ้ำ**
 *    ไม่งั้นจะเพี้ยนสองต่อ
 */
/** ความถี่จริง (Hz) ของโน้ต MIDI ตัวนี้ในระบบที่เลือก
 *
 *  ★ ใช้กับ **ชุดเสียงสังเคราะห์** ซึ่งตั้งความถี่ได้ตรง ๆ (ต่างจากแซมเปิลที่ทำได้
 *    แค่ดัดความเร็วจากไฟล์ที่อัดมา) ผลที่ได้คือ **ตัวเลขในตารางทางการเป๊ะ ๆ**
 *    เช่น พระราชทาน ล = 828.00 Hz · กรมศิลป์ ด = 230.30 Hz
 *  ★ ความคลาดของคู่แปดเล็ก ๆ (เช่น royal 252→505 ไม่ใช่ 504) **มีอยู่ในตาราง
 *    ต้นฉบับเอง** — จงใจไม่ไป "แก้" ให้ลงตัว ตามกฎที่หัวไฟล์นี้ */
export const noteHz = (midi, system) =>
  440 * Math.pow(2, (midi - 69) / 12) * tuningRatio(midi, system);

export function tuningRatio(midi, system) {
  if (system === 'chromatic' || midi == null) return 1;
  const n = WHITE[((midi % 12) + 12) % 12];
  if (n === undefined) return 1;
  const midiOctave = Math.floor(midi / 12) - 1;   // MIDI 60 = C4 → 4
  const table = system === 'royal' ? ROYAL : SILPA;
  let idx = system === 'royal' ? midiOctave - 1 : midiOctave - 3;
  // ★ โน้ตที่หลุดช่วงตาราง (เช่น ซฺ ลฺ ทฺ เสียงต่ำที่เพิ่มให้โน้ตบรรทัดเดียว 2026-07-24)
  //   ยืมแถวที่ใกล้ที่สุดแล้วขยับทีละคู่แปด — คู่แปดเป็น 2:1 เป๊ะทั้งสองระบบ
  //   (ยังใช้ตัวเลขในตารางเป็นตัวตั้งเสมอ ไม่ได้คำนวณ 7 เสียงในคู่แปดขึ้นมาเอง)
  //   ★ ของเดิมคืน 1 เฉย ๆ = โน้ตตัวนั้นดังเป็นเสียงสากลอยู่ตัวเดียวทั้งเพลง
  let mul = 1;
  const rows = Object.keys(table).map(Number);
  const lo = Math.min(...rows), hi = Math.max(...rows);
  while (idx < lo) { idx += 1; mul /= 2; }
  while (idx > hi) { idx -= 1; mul *= 2; }
  const row = table[idx];
  if (!row) return 1;
  const etHz = 440 * Math.pow(2, (midi - 69) / 12); // ความถี่สากลของโน้ตนี้
  return (row[n] * mul) / etHz;
}
