// ════════════════════════════════════════════════════════════════════
//  ส่งออกเป็นไฟล์ MIDI (.mid) — เอาไปเปิดใน DAW / โปรแกรมโน้ต / เครื่องเล่นทั่วไป
//
//  ★ ต่างจาก MusicXML ตรงที่มาของข้อมูล และตั้งใจให้ต่างกัน:
//      MusicXML = "สิ่งที่อ่าน"  → สร้างจากโมเดลโน้ตสากล (western_score.mjs)
//      MIDI     = "สิ่งที่ได้ยิน" → สร้างจากไทม์ไลน์ notes[] ตัวเดียวกับที่เครื่องเล่นใช้
//    ไฟล์ MIDI จึงมีทั้งเครื่องหมายตีเหลื่อมและจังหวะสะบัดจริงครบ (โน้ตบนกระดาษ
//    เขียนเป็นเครื่องหมายกำกับ เพราะรายละเอียดระดับ 1/8 ช่องเขียนเป็นตัวโน้ตไม่ได้)
//
//  ★ กติกาเวลา: 1 ห้อง = 1 จังหวะ → ticksPerBeat = ticksPerHong (เหมือน
//    tool/thai_score_to_song.py ฝั่ง KHIM เป๊ะ ไฟล์จากสองทางจึงเล่นเหมือนกัน)
//  ★ เจ้าของสั่ง 2026-07-24: ให้ดาวน์โหลดได้ **เฉพาะสมาชิก**
// ════════════════════════════════════════════════════════════════════

/** เสียงเครื่องดนตรีตามมาตรฐาน General MIDI (ใกล้เคียงที่สุดเท่าที่ GM มี) */
const GM_PROGRAM = {
  khlui_phiang_o: 13,   // Xylophone — เครื่องตีที่มีคีย์ (เปลี่ยนจากขลุ่ยเป็นระนาดเอกจริง 2026-07-29)
  khong_wong_yai: 12,   // Marimba — เครื่องตีที่มีคีย์ ใกล้เสียงฆ้องวงกว่าตัวอื่นใน GM
};
const DEFAULT_PROGRAM = 12;

// ฉิ่ง/ฉับ ในแทร็กเครื่องประกอบจังหวะ (ช่อง 10 ของ GM = ช่องเครื่องกระทบ)
const GM_CHING = 81;  // Open Triangle — เสียงปล่อยกังวาน (ฉิ่ง)
const GM_CHAP = 80;   // Mute Triangle — เสียงปิด (ฉับ)

/** ตัวเลขแบบ variable-length ของ MIDI */
function vlq(n) {
  const out = [n & 0x7f];
  n >>= 7;
  while (n > 0) {
    out.unshift((n & 0x7f) | 0x80);
    n >>= 7;
  }
  return out;
}

const str = (s) => Array.from(new TextEncoder().encode(s));

/** ต่อ track chunk (ใส่ End of Track ให้เอง) */
function trackChunk(events) {
  const body = [...events, 0x00, 0xff, 0x2f, 0x00];
  const len = body.length;
  return [
    0x4d, 0x54, 0x72, 0x6b,
    (len >> 24) & 0xff, (len >> 16) & 0xff, (len >> 8) & 0xff, len & 0xff,
    ...body,
  ];
}

/** เหตุการณ์ [tick, order, bytes] → ไบต์ของแทร็ก (คิด delta ให้) */
function toDeltas(events) {
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const out = [];
  let prev = 0;
  for (const [tick, , data] of events) {
    out.push(...vlq(Math.max(0, Math.round(tick - prev))), ...data);
    prev = tick;
  }
  return out;
}

/**
 * เพลง (รูปแบบ .json ของเว็บ) → ไฟล์ MIDI (Uint8Array)
 * @param opts.withChing  ใส่แทร็กฉิ่ง-ฉับด้วยไหม (ค่าเริ่มต้น: ใส่)
 * @param opts.title      ชื่อเพลงที่เขียนลงไฟล์
 */
export function songToMidi(song, opts = {}) {
  const tpb = Math.max(1, Math.round(Number(song.ticksPerHong) || 480));
  const bpm = Number(song.bpm) || 60;
  const withChing = opts.withChing !== false;
  const toMidi = (i) => (song.indexToMidi || [])[i];

  // ── แทร็ก 0: ชื่อเพลง + ความเร็ว ──
  const usec = Math.round(60000000 / bpm);
  const title = str((opts.title || song.title || 'Thai score').slice(0, 120));
  const meta = [
    0x00, 0xff, 0x03, ...vlq(title.length), ...title,            // Track name
    0x00, 0xff, 0x51, 0x03, (usec >> 16) & 0xff, (usec >> 8) & 0xff, usec & 0xff, // Tempo
    0x00, 0xff, 0x58, 0x04, 2, 2, 24, 8,                          // Time signature 2/4
  ];

  // ── แทร็ก 1: ทำนอง (ช่อง 1) ──
  const program = GM_PROGRAM[song.instrument] ?? DEFAULT_PROGRAM;
  const mel = [[0, -1, [0xc0, program]]];
  for (const n of song.notes || []) {
    const pitch = toMidi(n.i);
    if (pitch === undefined) continue;
    const t = Math.round(n.t);
    const d = Math.max(1, Math.round(n.d));
    mel.push([t, 1, [0x90, pitch, 100]]);
    mel.push([t + d, 0, [0x80, pitch, 0]]);
  }

  const tracks = [trackChunk(meta), trackChunk(toDeltas(mel))];

  // ── แทร็ก 2: ฉิ่ง-ฉับ (ช่อง 10 = เครื่องกระทบตามมาตรฐาน GM) ──
  if (withChing && (song.ching || []).length) {
    const ch = [];
    for (const c of song.ching) {
      const pitch = c.type === 0 ? GM_CHING : GM_CHAP;
      const t = Math.round(c.t);
      ch.push([t, 1, [0x99, pitch, 90]]);
      ch.push([t + Math.round(tpb / 4), 0, [0x89, pitch, 0]]);
    }
    tracks.push(trackChunk(toDeltas(ch)));
  }

  const head = [
    0x4d, 0x54, 0x68, 0x64, 0, 0, 0, 6,
    0, 1,                                   // format 1 (หลายแทร็ก)
    0, tracks.length,
    (tpb >> 8) & 0xff, tpb & 0xff,
  ];
  return new Uint8Array([...head, ...tracks.flat()]);
}
