// ════════════════════════════════════════════════════════════════════
//  เปิด / บันทึก / ส่งออก — คุยกับ Tauri
//
//  ★ ไฟล์งานคือ `.thscore` (JSON ข้างใน) · เปิด JSON เปล่าจากเว็บได้ด้วย
//  ★ "ส่งขึ้นเว็บ" เขียน JSON รูปเว็บล้วน ๆ ไม่มีซอง — เว็บไม่รู้จักซองและไม่ต้องรู้จัก
// ════════════════════════════════════════════════════════════════════
import { open, save, message } from '@tauri-apps/plugin-dialog';
import { MUSICXML_SOFTWARE } from './version';
import { readTextFile, writeTextFile, writeFile } from '@tauri-apps/plugin-fs';
import { invoke } from '@tauri-apps/api/core';
import { readThscore, writeThscore, toWebsiteJson, suggestFileName } from '../../packages/engine-ext/thscore_file.mjs';
import { songToMusicXml } from '../../packages/engine/musicxml.mjs';
import { songToMidi } from '../../packages/engine/midi.mjs';
import type { Doc } from './doc';
import { t } from './i18n';

/** ★ ตัวกรองไฟล์ต้องเป็น **ฟังก์ชัน** — กล่องเปิด/บันทึกของ Windows อ่านชื่อ
 *  ตอนถูกเรียก ถ้าเก็บเป็นค่าคงที่ระดับโมดูล ชื่อจะค้างภาษาแรกที่โหลดตลอดอายุโปรแกรม */
const scoreFilters = () => [
  { name: t('โน้ตเพลงไทย'), extensions: ['thscore', 'json'] },
];

export async function openScore(): Promise<{ doc: Doc; path: string } | null> {
  const picked = await open({ multiple: false, filters: scoreFilters(), title: t('เปิดไฟล์โน้ต') });
  if (!picked || typeof picked !== 'string') return null;
  const raw = await readTextFile(picked);
  const { doc, error } = readThscore(raw);
  if (error || !doc) {
    await message(error || t('เปิดไฟล์นี้ไม่ได้'), { title: t('เปิดไฟล์ไม่สำเร็จ'), kind: 'error' });
    return null;
  }
  return { doc, path: picked };
}

export async function openScoreAt(path: string): Promise<Doc | null> {
  try {
    const raw = await readTextFile(path);
    const { doc, error } = readThscore(raw);
    if (error || !doc) return null;
    return doc;
  } catch {
    return null;
  }
}

export async function saveScore(doc: Doc, path: string | null, appVersion: string): Promise<string | null> {
  let target = path;
  if (!target) {
    const picked = await save({
      title: t('บันทึกโน้ต'),
      defaultPath: suggestFileName(doc.song, 'thscore'),
      filters: [{ name: t('โน้ตเพลงไทย (.thscore)'), extensions: ['thscore'] }],
    });
    if (!picked) return null;
    target = picked;
  }
  try {
    await writeTextFile(target, writeThscore(doc, appVersion));
    return target;
  } catch (e) {
    await message((e as Error).message, { title: t('บันทึกไม่สำเร็จ'), kind: 'error' });
    return null;
  }
}

export async function exportMusicXml(doc: Doc) {
  const picked = await save({
    title: t('ส่งออก MusicXML'),
    defaultPath: suggestFileName(doc.song, 'musicxml'),
    filters: [{ name: 'MusicXML', extensions: ['musicxml', 'xml'] }],
  });
  if (!picked) return;
  try {
    // ★★ ข้อมูลกำกับที่ทำให้ไฟล์ "เอาไปอ้างอิงทางวิชาการได้" — ใครถอด · ด้วยอะไร · เมื่อไร
    //    ไฟล์ที่ไม่มีสามอย่างนี้ลงบรรณานุกรมไม่ได้ (เจ้าของสั่ง 2026-08-05)
    //    ★ `software` ต้องส่งเสมอ — ค่าตั้งต้นในเอนจินเป็นชื่อเว็บ ซึ่งห้ามหลุดออกไป
    //      ในไฟล์ของลูกค้า (ดู MUSICXML_SOFTWARE ใน lib/version.ts)
    //    ★ ไม่ส่ง `rights` — กระดาษและไฟล์เป็นของลูกค้า เราไม่ประทับสิทธิ์ของเราลงไป
    //    ★ วันที่เป็นวันที่ "เขียนไฟล์นี้" ตามรูปแบบ YYYY-MM-DD ที่สเปกกำหนด
    const xml = songToMusicXml(doc.song, {
      barPhase: doc.view.barPhase,
      title: doc.song.title,
      credit: doc.song.writer || '',
      partName: doc.song.instrumentTh || '',
      software: MUSICXML_SOFTWARE,
      encodingDate: new Date().toISOString().slice(0, 10),
      tuningNote: true,
      // ★★ ตามสวิตช์ "รวบเป็นบรรทัดเดียว" บนหัวแผ่นสากล (เจ้าของสั่ง 2026-08-17) ★★
      //   สิ่งที่เห็นบนจอ = สิ่งที่ได้ในไฟล์ · ไฟล์ที่รวบแล้วจะเป็น <staves>1
      //   และเสียงที่ตกจังหวะเดียวกันเขียนติด <chord/> ให้เอง
      merge: doc.page.wnMerge === true,
    });
    await writeTextFile(picked, xml);
    await message(t('เปิดต่อได้ใน MuseScore, Sibelius, Finale'), { title: t('ส่งออกแล้ว') });
  } catch (e) {
    await message((e as Error).message, { title: 'ส่งออกไม่สำเร็จ', kind: 'error' });
  }
}

export async function exportMidi(doc: Doc) {
  const picked = await save({
    title: t('ส่งออก MIDI'),
    defaultPath: suggestFileName(doc.song, 'mid'),
    filters: [{ name: 'MIDI', extensions: ['mid', 'midi'] }],
  });
  if (!picked) return;
  // ★★ ต้องมีตัวรับ error เสมอ — ของเดิมไม่มี และ `writeFile` (เขียนไบนารี) ถูกปฏิเสธ
  //    ตั้งแต่ต้นเพราะ capabilities ไม่ได้ประกาศ `fs:allow-write-file` ไว้
  //    ผลคือ **ผู้ใช้เลือกชื่อไฟล์แล้วเงียบสนิท ไม่มีอะไรฟ้องเลย** ทั้งที่หน้าแรก/กล่อง
  //    เกี่ยวกับ/วิธีใช้/คำบรรยายตัวติดตั้ง โฆษณาว่าส่งออก MIDI ได้ (เจอ 2026-07-31)
  // ★ writeTextFile เขียนไบนารีไม่ได้ (มันแปลงเป็น UTF-8) — MIDI ต้องใช้ writeFile เท่านั้น
  try {
    const buf = songToMidi(doc.song, { title: doc.song.title });
    await writeFile(picked, new Uint8Array(buf));
    await message(t('เอาไปเปิดต่อใน DAW ได้เลย'), { title: t('ส่งออกแล้ว') });
  } catch (e) {
    await message((e as Error).message, { title: 'ส่งออกไม่สำเร็จ', kind: 'error' });
  }
}

export async function exportWebsiteJson(doc: Doc) {
  const picked = await save({
    // ★ ชื่อกล่องบันทึกไฟล์ที่ผู้ใช้เห็น — ห้ามเอ่ยชื่อเว็บของเรา (เจ้าของสั่ง 2026-07-31)
    title: t('ส่งออกไฟล์ JSON'),
    defaultPath: suggestFileName(doc.song, 'json'),
    filters: [{ name: 'JSON', extensions: ['json'] }],
  });
  if (!picked) return;
  try {
    await writeTextFile(picked, toWebsiteJson(doc));
    await message(t('เอาไฟล์นี้ไปแปะที่ /admin/scores/new บนเว็บได้เลย'), { title: t('ส่งออกแล้ว') });
  } catch (e) {
    await message((e as Error).message, { title: 'ส่งออกไม่สำเร็จ', kind: 'error' });
  }
}

// ── PDF ─────────────────────────────────────────────────────────────
export type PdfBackend = { engine: string; silent: boolean };

export async function pdfBackend(): Promise<PdfBackend> {
  try {
    return await invoke<PdfBackend>('pdf_backend');
  } catch {
    return { engine: 'window.print()', silent: false };
  }
}

/* ════════════════════════════════════════════════════════════════════
   ★★ "พิมพ์" กับ "บันทึกเป็น PDF" เป็นสองงานคนละอย่าง ห้ามยุบรวมอีก ★★
   เจ้าของทัก 2026-07-30: "พิมพ์ กับ บันทึก มันเป็นการทำงานเดียวกันอยู่" — ถูกต้อง
   ของเดิมมีแต่ทางบันทึกไฟล์ (printPdf) แล้วเอาไปแปะชื่อเมนูว่า "พิมพ์ / บันทึก PDF…"
   ทั้งที่ **ไม่มีทางส่งงานไปเครื่องพิมพ์เลยแม้แต่ทางเดียว** ขณะที่หน้าแรก/About/
   วิธีใช้ โฆษณาว่า "พิมพ์ลงกระดาษ A4" ได้
     · printPaper() → กล่องพิมพ์จริง เลือกเครื่องพิมพ์ได้ (เมนู ไฟล์ → พิมพ์…)
     · printPdf()   → บันทึกเป็นไฟล์ PDF (เมนู ส่งออก → PDF)
   ════════════════════════════════════════════════════════════════════ */

/** ใส่กฎ @page ให้ตรงกับ "ตั้งค่าหน้ากระดาษ" ก่อนสั่งพิมพ์จริง
 *  ★ งานพิมพ์ออกกระดาษคุมขอบจากที่นี่ ไม่ใช่จากฝั่ง Rust (ต่างจาก print_to_pdf
 *    ที่ส่ง margin เป็นพารามิเตอร์ได้) · @page ในไฟล์ app.css ตั้ง margin:0 ไว้
 *    สำหรับทาง PDF — ถ้าไม่ทับค่าตรงนี้ งานพิมพ์จริงจะไม่มีขอบกระดาษเลย
 *    และเครื่องพิมพ์ส่วนใหญ่พิมพ์ชิดขอบไม่ได้ = เนื้อหาริมกระดาษหาย */
const PAGE_RULE_ID = 'ts-print-page-rule';
function applyPageRule(doc: Doc) {
  const el = document.getElementById(PAGE_RULE_ID) || (() => {
    const s = document.createElement('style');
    s.id = PAGE_RULE_ID;
    document.head.appendChild(s);
    return s;
  })();
  const mm = Number(doc.page.marginMm) || 12;
  const dir = doc.page.orientation === 'landscape' ? 'landscape' : 'portrait';
  el.textContent = `@media print { @page { size: A4 ${dir}; margin: ${mm}mm; } }`;
}

/** `toFile` = สั่งพิมพ์แล้วได้ไฟล์ ไม่ใช่กระดาษ (Microsoft Print to PDF ฯลฯ) */
export type Printer = { name: string; isDefault: boolean; toFile: boolean };

/** รายชื่อเครื่องพิมพ์ในเครื่อง — ว่าง = ไม่มีเครื่องพิมพ์ หรือแพลตฟอร์มยังไม่รองรับ
 *  ★ ฝั่ง Rust แยกมาให้แล้วว่าตัวไหน "พิมพ์ลงไฟล์" (ดูพอร์ต PORTPROMPT:/FILE:/nul:
 *    และชื่อไดรเวอร์) — กล่องพิมพ์ต้องบอกผู้ใช้ก่อนกด ไม่ใช่ให้ไปเจอกล่องบันทึกไฟล์
 *    แล้วเข้าใจว่าโปรแกรมพิมพ์ไม่ออก (เจ้าของเจอเองบนเครื่องที่ไม่มีเครื่องพิมพ์จริง) */
export async function listPrinters(): Promise<Printer[]> {
  try {
    const raw = await invoke<Array<{ name: string; is_default: boolean; to_file?: boolean }>>('list_printers');
    return (raw || []).map((p) => ({
      name: p.name,
      isDefault: !!p.is_default,
      toFile: !!p.to_file,
    }));
  } catch {
    return [];
  }
}

/**
 * สั่งพิมพ์ออกเครื่องพิมพ์ที่เลือก — ไม่มีกล่องของระบบโผล่
 * ★ ทุกค่าคุมจากเรา: ไม่มีหัว-ท้ายกระดาษ · พิมพ์พื้นสี · ขอบตาม "ตั้งค่าหน้ากระดาษ"
 *   เหตุผลว่าทำไมไม่ใช้กล่องของตัวแสดงผล อยู่ใน src-tauri/src/printing.rs
 */
export async function printToPrinter(doc: Doc, printer: string, copies = 1): Promise<void> {
  applyPageRule(doc);
  await invoke('print_to_printer', {
    printer,
    copies,
    landscape: doc.page.orientation === 'landscape',
    marginsMm: doc.page.marginMm,
  });
}

/**
 * ทางถอย — เปิดกล่องพิมพ์ของระบบ (ใช้เมื่อเรียงเครื่องพิมพ์เองไม่ได้)
 * ⚠ กล่องนี้แปะวันที่/ชื่อโปรแกรม/ที่อยู่หน้าลงบนกระดาษเป็นค่าตั้งต้น สั่งปิดจากโค้ดไม่ได้
 */
export async function printViaSystemDialog(doc: Doc): Promise<void> {
  applyPageRule(doc);
  try {
    // ★ ต้องส่ง landscape ไปด้วย — macOS อ่านแนวกระดาษจาก NSPrintInfo
    //   ไม่ใช่จากกฎ @page ของ CSS (ต่างจาก Chromium ฝั่ง Windows)
    //   ถ้าไม่ส่ง ปุ่ม "แนวนอน" ในกล่องตั้งค่าหน้ากระดาษจะกดแล้วไม่มีผล
    await invoke('show_print_ui', { landscape: doc.page.orientation === 'landscape' });
  } catch {
    window.print();
  }
}

/**
 * บันทึกเป็นไฟล์ PDF (ไม่ใช่การพิมพ์ออกกระดาษ)
 * ★ Windows ใช้ PrintToPdf ของ WebView2 = ไม่มีกล่องพิมพ์ คุมขอบกระดาษเองได้
 *   แพลตฟอร์มอื่นถอยไป window.print() (ผู้ใช้เลือก "Save as PDF" เอง)
 */
export async function printPdf(doc: Doc): Promise<string | null> {
  const backend = await pdfBackend();
  if (!backend.silent) {
    // ★★ macOS: ห้ามใช้ window.print() ★★ WKWebView ไม่มีตัวรับ printFrame:
    //   กดแล้วเงียบสนิทไม่มี error — ต้องเปิดกล่องพิมพ์ของ macOS แทน
    //   ซึ่งมีปุ่ม PDF → "Save as PDF" ให้ผู้ใช้บันทึกไฟล์ได้จริง
    //   ★ ต้องใส่กฎ @page ก่อน ไม่งั้น WebKit ตัดหน้าตามผังหน้าจอ
    if (backend.engine === 'mac-print-dialog') {
      return withPrintWhat(doc, async () => {
        applyPageRule(doc);
        await printViaSystemDialog(doc);
        return null;
      });
    }
    window.print();
    return null;
  }
  const picked = await save({
    title: t('บันทึกเป็น PDF'),
    defaultPath: suggestFileName(doc.song, 'pdf'),
    filters: [{ name: 'PDF', extensions: ['pdf'] }],
  });
  if (!picked) return null;
  return withPrintWhat(doc, async () => {
    try {
      return await invoke<string>('print_to_pdf', {
        path: picked,
        landscape: doc.page.orientation === 'landscape',
        marginsMm: doc.page.marginMm,
      });
    } catch (e) {
      await message(String(e), { title: t('พิมพ์ PDF ไม่สำเร็จ'), kind: 'error' });
      return null;
    }
  });
}

/**
 * สั่งพิมพ์โดยบังคับว่า "พิมพ์อะไรบ้าง" เป็นค่าของ doc ที่ส่งมา แล้วคืนค่าเดิมให้เสมอ
 *
 * ★★ ทำไมต้องมี ★★
 *   ตัวที่ตัดสินว่าแผงไหนจะติดไปบนกระดาษคือ **แอตทริบิวต์ `data-print-what` ที่ `<html>`**
 *   (ดูกฎ `html[data-print-what=…] .print-pane--…` ใน app.css) ซึ่ง Editor.tsx ตั้งจาก
 *   doc **ตัวจริงที่ผู้ใช้เปิดอยู่** — การส่ง doc ที่แก้ `page.what` เข้ามาเฉย ๆ
 *   จึงไม่มีผลอะไรเลย ได้ไฟล์หน้าตาเดิมทุกครั้งโดยไม่มีอะไรฟ้อง (โดนมาแล้ว 2026-08-07)
 *   ★ กล่องส่งออกให้เลือก "PDF กระดาษไทย" กับ "PDF โน้ตสากล" แยกกัน จึงต้องพึ่งท่านี้
 *   ★ คืนค่าเดิมใน finally เสมอ — ไม่งั้นหน้าจอที่ผู้ใช้เห็นค้างอยู่ที่โหมดพิมพ์ครั้งล่าสุด
 */
async function withPrintWhat<T>(doc: Doc, run: () => Promise<T>): Promise<T> {
  const el = document.documentElement;
  const prev = el.getAttribute('data-print-what');
  el.setAttribute('data-print-what', doc.page.what || 'both');
  try {
    return await run();
  } finally {
    if (prev === null) el.removeAttribute('data-print-what');
    else el.setAttribute('data-print-what', prev);
  }
}
