// ════════════════════════════════════════════════════════════════════
//  "คิวเที่ยว" — ลำดับท่อนที่จะเล่นจริง เช่น ท่อน1,ท่อน1,ท่อน2,ท่อน2,…
//
//  ทำให้ "ซ้ำท่อน" เป็นเรื่องของ *ลำดับการเล่น* ไม่ใช่การเขียนโน้ตซ้ำลงกระดาษ
//  (คนเขียนโน้ตเขียนท่อนเดียว แล้วบอกว่า "2 เที่ยว" — กระดาษจึงไม่บวม)
//
//  ★★ ทำไมต้องเป็นไฟล์กลาง (แยกออกมา 2026-08-03)
//     เดิมสูตรนี้อยู่ใน score_player.ts (หน้าเพลงของคนเข้าเว็บ) ที่เดียว
//     หน้าเขียนโน้ตของสมาชิกจึงเล่นรวดเดียวจบ ไม่ย้อนท่อนให้เลย — สมาชิก
//     รายงานเข้ามาเองว่า "กด play แล้วมันไม่กลับต้น" (2026-08-03)
//     ตอนนี้ทั้งสองหน้าเรียกไฟล์นี้ก้อนเดียวกัน จะซ้ำท่อนเพี้ยนคนละแบบไม่ได้อีก
//
//  ★ ไฟล์นี้เป็น pure function ล้วน ไม่แตะ DOM ไม่แตะ Web Audio
//    (เอนจินเสียงของสองหน้านั้นคนละตัวกัน และไม่ได้ตั้งใจจะรวมกัน)
// ════════════════════════════════════════════════════════════════════
import { lineStaves, staveCount, normalizeEnding } from './thai_score.mjs';

/** เพลงไทยราว 80-90% เล่นซ้ำท่อนตัวเองสองเที่ยวก่อนไปท่อนถัดไป (1-1/2-2/3-3)
 *  เจ้าของยืนยันเอง 2026-07-22 → ไม่ได้กำหนดมา = 2 เที่ยว */
export const DEFAULT_SECTION_REPEAT = 2;

/** จำนวนห้องของบรรทัดหนึ่ง — นับจากบรรทัดที่ยาวที่สุดในผัง
 *  ★ ห้ามอ่าน `ln.right.length` ตรง ๆ: เพลง ≥ 3 บรรทัดเก็บใน `staves[]`
 *    ไม่มีฟิลด์ right เลย (จะได้ 0 เงียบ ๆ = ท่อนกว้างศูนย์ ไม่มีเสียง) */
function lineHongCount(ln, nStaves) {
  return lineStaves(ln, nStaves).reduce((m, a) => Math.max(m, a?.length || 0), 0);
}

/**
 * ช่วง tick ของแต่ละท่อน + จำนวนเที่ยวที่ต้องเล่น
 * @returns [{ name, idx, startTick, endTick, repeat }]
 */
export function sectionSpans(song) {
  const tph = Number(song?.ticksPerHong) || 480;
  const nStaves = staveCount(song);
  const dflt = Number(song?.repeatSections) > 0 ? Number(song.repeatSections) : DEFAULT_SECTION_REPEAT;
  return (song?.sections || []).map((s, idx) => {
    const lines = s?.lines || [];
    const first = lines[0]?.firstHong ?? 0;
    const last = lines[lines.length - 1];
    const lastHong = (last?.firstHong ?? 0) + lineHongCount(last, nStaves);
    // ★ ใส่ฟิลด์ `endings` **เฉพาะตอนมีจริง** — เพลงที่ไม่มีเที่ยวเปลี่ยนต้องได้
    //   ผลลัพธ์เท่าเดิมทุกไบต์ (ของเก่าไม่มีทางพังจากงานนี้ · เทสต์เทียบทั้งก้อนอยู่)
    const ends = endingSpans(s, lines, nStaves, tph);
    return {
      name: s?.name || '',
      idx,
      startTick: first * tph,
      endTick: lastHong * tph,
      repeat: Number(s?.repeat) > 0 ? Number(s.repeat) : dflt,
      ...(ends.length ? { endings: ends } : {}),
    };
  });
}

/**
 * ช่วง tick ของห้องที่ติดป้ายเที่ยวเปลี่ยนในท่อนหนึ่ง
 * @returns [{ pass, startTick, endTick }]  pass = เล่นเฉพาะเที่ยวที่เท่าไร
 *
 * ★ ห้องที่ติดป้ายเลขเดียวกันและอยู่ติดกัน รวมเป็นช่วงเดียว (วงเล็บคลุมหลายห้องได้)
 */
function endingSpans(sec, lines, nStaves, tph) {
  const out = [];
  for (const ln of lines || []) {
    const n = lineHongCount(ln, nStaves);
    const first = ln?.firstHong ?? 0;
    for (let h = 0; h < n; h++) {
      const pass = normalizeEnding(ln?.endings?.[h]);
      if (!pass) continue;
      const startTick = (first + h) * tph;
      const prev = out[out.length - 1];
      // ต่อจากช่วงเดิมถ้าเลขเดียวกันและห้องติดกันพอดี
      if (prev && prev.pass === pass && prev.endTick === startTick) prev.endTick += tph;
      else out.push({ pass, startTick, endTick: startTick + tph });
    }
  }
  return out;
}

/**
 * คิวเที่ยวจากช่วงท่อนที่คำนวณไว้แล้ว
 *
 * ★ แยกจาก buildPlayQueue เพราะหน้าเพลงคำนวณช่วงท่อนตั้งแต่ฝั่งเซิร์ฟเวอร์
 *   (ฝังมากับหน้าเป็น #sp-sections) ส่วนหน้าเขียนโน้ตคำนวณสด ๆ ทุกครั้งที่กดเล่น
 *   — คนละจังหวะกัน แต่ต้องได้คิวสูตรเดียวกัน
 *
 * @param spans  [{ startTick, endTick, repeat, … }]
 * @param opts   { repeat = true (ปิด = ท่อนละเที่ยวเดียว) · only = -1 (idx ท่อน = เล่นเฉพาะท่อนนั้น)
 *                 · totalTicks = ความยาวทั้งเพลง (ใช้ตอนคิวว่าง) }
 * @returns [{ s, e, sec, pass, of }]  s/e = tick ต้น-ปลายของช่วง · pass = เที่ยวที่เท่าไร จาก of
 */
export function buildQueueFromSpans(spans, opts = {}) {
  const { repeat = true, only = -1, totalTicks = 0 } = opts;
  const all = spans || [];
  const list = only >= 0 && all[only] ? [all[only]] : all;
  const q = [];
  for (const s of list) {
    // ท่อนกว้างศูนย์ (ไฟล์เพี้ยน/ท่อนที่เพิ่งเพิ่มยังไม่มีห้อง) — ข้าม ไม่งั้นคิวค้างที่ช่วงว่าง
    if (!(s.endTick > s.startTick)) continue;
    const n = repeat ? Math.max(1, s.repeat || 1) : 1;
    for (let p = 1; p <= n; p++) {
      // ★★ เที่ยวเปลี่ยน — เที่ยวนี้ต้อง **ข้าม** ห้องที่ติดป้ายของเที่ยวอื่น
      //    (คนเขียนโน้ตเขียนห้องของทุกเที่ยวต่อกันบนกระดาษ เหมือนแผ่นโน้ตจริง)
      const skip = (s.endings || []).filter((x) => x.pass !== p)
        .sort((a, b) => a.startTick - b.startTick);
      if (!skip.length) { q.push({ s: s.startTick, e: s.endTick, sec: s, pass: p, of: n }); continue; }
      let at = s.startTick;
      for (const gap of skip) {
        if (gap.startTick > at) q.push({ s: at, e: gap.startTick, sec: s, pass: p, of: n });
        at = Math.max(at, gap.endTick);
      }
      if (s.endTick > at) q.push({ s: at, e: s.endTick, sec: s, pass: p, of: n });
    }
  }
  // กันกรณีข้อมูลเพี้ยนจนคิวว่าง — ให้เล่นทั้งเพลงรวดเดียว ดีกว่าเงียบสนิท
  return q.length ? q : [{ s: 0, e: Number(totalTicks) || 0, sec: null, pass: 1, of: 1 }];
}

/** คิวเที่ยวจากตัวเพลงตรง ๆ (คำนวณช่วงท่อนให้เอง) */
export function buildPlayQueue(song, opts = {}) {
  return buildQueueFromSpans(sectionSpans(song), {
    totalTicks: Number(song?.lengthTicks) || 0,
    ...opts,
  });
}

/**
 * กางไทม์ไลน์ตามคิว — สำหรับเครื่องเล่นที่รับ notes/ching เป็นเส้นตรงเส้นเดียว
 * (หน้าเขียนโน้ตใช้ตัวนี้ · หน้าเพลงไม่ต้องใช้ เพราะมันเดินคิวเองทีละช่วง)
 *
 * ★ คืน `segs` มาด้วยเสมอ ไว้แปลง "tick บนไทม์ไลน์ที่กางแล้ว" กลับเป็น
 *   "tick ของกระดาษจริง" — ไม่งั้นพอเล่นเที่ยวสอง หัวเข็มจะวิ่งเลยกระดาษไป
 *
 * @returns { notes, ching, lengthTicks, segs }
 */
export function expandForPlayback(song, queue) {
  const notes = [], ching = [], segs = [];
  const srcNotes = (song?.notes || []).slice().sort((a, b) => a.t - b.t);
  const srcChing = (song?.ching || []).slice().sort((a, b) => a.t - b.t);
  let cursor = 0;
  for (const q of queue) {
    const len = q.e - q.s;
    if (!(len > 0)) continue;
    const shift = cursor - q.s;
    for (const n of srcNotes) {
      // ★ `< q.e` ไม่ใช่ `<=` — โน้ตที่ตกตรงรอยต่อพอดีเป็นของท่อนถัดไป
      //   (ใช้ `<=` เมื่อไร ตัวแรกของทุกท่อนจะดังซ้อนสองครั้ง)
      if (n.t >= q.s && n.t < q.e) notes.push({ ...n, t: n.t + shift });
    }
    for (const c of srcChing) {
      if (c.t >= q.s && c.t < q.e) ching.push({ ...c, t: c.t + shift });
    }
    segs.push({ from: cursor, to: cursor + len, src: q.s, sec: q.sec, pass: q.pass, of: q.of });
    cursor += len;
  }
  return { notes, ching, lengthTicks: cursor, segs };
}

/** tick บนไทม์ไลน์ที่กางแล้ว → tick ของกระดาษจริง (ไว้ทาหัวเข็ม) */
export function toSourceTick(segs, t) {
  for (const g of segs) if (t >= g.from && t < g.to) return g.src + (t - g.from);
  const last = segs[segs.length - 1];
  return last ? last.src + Math.max(0, last.to - last.from - 1) : t;
}

/** tick ของกระดาษจริง → tick บนไทม์ไลน์ที่กางแล้ว (เที่ยวแรกที่เจอ)
 *  ไว้ให้ปุ่ม "เล่นจากห้องที่เลือก" เริ่มถูกที่หลังกางคิวแล้ว */
export function toPlaybackTick(segs, t) {
  for (const g of segs) if (t >= g.src && t < g.src + (g.to - g.from)) return g.from + (t - g.src);
  return 0;
}
